//! Minimal cell-buffer based terminal rendering layer.

use std::io::{self, Write};

use crossterm::{
    cursor::{Hide, MoveTo, Show},
    queue,
    style::{Attribute, Color as CColor, Colors, Print, SetAttribute, SetColors},
    terminal,
};
use unicode_width::UnicodeWidthStr;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Color {
    Reset,
    Black,
    Red,
    Green,
    Yellow,
    Blue,
    Magenta,
    Cyan,
    Gray,
    DarkGray,
    LightRed,
    LightGreen,
    LightYellow,
    LightBlue,
    LightMagenta,
    LightCyan,
    White,
    Indexed(u8),
    Rgb(u8, u8, u8),
}

impl Color {
    fn to_crossterm(self) -> CColor {
        match self {
            Color::Reset => CColor::Reset,
            Color::Black => CColor::Black,
            Color::Red => CColor::DarkRed,
            Color::Green => CColor::DarkGreen,
            Color::Yellow => CColor::DarkYellow,
            Color::Blue => CColor::DarkBlue,
            Color::Magenta => CColor::DarkMagenta,
            Color::Cyan => CColor::DarkCyan,
            Color::Gray => CColor::Grey,
            Color::DarkGray => CColor::DarkGrey,
            Color::LightRed => CColor::Red,
            Color::LightGreen => CColor::Green,
            Color::LightYellow => CColor::Yellow,
            Color::LightBlue => CColor::Blue,
            Color::LightMagenta => CColor::Magenta,
            Color::LightCyan => CColor::Cyan,
            Color::White => CColor::White,
            Color::Indexed(i) => CColor::AnsiValue(i),
            Color::Rgb(r, g, b) => CColor::Rgb { r, g, b },
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub struct Modifier(pub u16);

impl Modifier {
    pub const NONE: Modifier = Modifier(0);
    pub const BOLD: Modifier = Modifier(1 << 0);
    pub const DIM: Modifier = Modifier(1 << 1);
    pub const ITALIC: Modifier = Modifier(1 << 2);
    pub const UNDERLINED: Modifier = Modifier(1 << 3);
    pub const SLOW_BLINK: Modifier = Modifier(1 << 4);
    pub const RAPID_BLINK: Modifier = Modifier(1 << 5);
    pub const REVERSED: Modifier = Modifier(1 << 6);
    pub const HIDDEN: Modifier = Modifier(1 << 7);
    pub const CROSSED_OUT: Modifier = Modifier(1 << 8);

    pub fn contains(self, other: Modifier) -> bool {
        self.0 & other.0 == other.0
    }
    pub fn insert(&mut self, other: Modifier) {
        self.0 |= other.0;
    }
    pub fn remove(&mut self, other: Modifier) {
        self.0 &= !other.0;
    }
    pub fn difference(self, other: Modifier) -> Modifier {
        Modifier(self.0 & !other.0)
    }
    pub fn is_empty(self) -> bool {
        self.0 == 0
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Style {
    pub fg: Color,
    pub bg: Color,
    pub modifier: Modifier,
}

impl Default for Style {
    fn default() -> Self {
        Style { fg: Color::Reset, bg: Color::Reset, modifier: Modifier::NONE }
    }
}

impl Style {
    pub fn new() -> Style {
        Style::default()
    }
    pub fn fg(mut self, c: Color) -> Style {
        self.fg = c;
        self
    }
    pub fn bg(mut self, c: Color) -> Style {
        self.bg = c;
        self
    }
    pub fn modifier(mut self, m: Modifier) -> Style {
        self.modifier.insert(m);
        self
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Cell {
    pub symbol: String,
    pub fg: Color,
    pub bg: Color,
    pub modifier: Modifier,
}

impl Default for Cell {
    fn default() -> Self {
        Cell { symbol: " ".to_string(), fg: Color::Reset, bg: Color::Reset, modifier: Modifier::NONE }
    }
}

impl Cell {
    pub fn set_symbol(&mut self, s: &str) {
        self.symbol.clear();
        self.symbol.push_str(s);
    }
    pub fn set_style(&mut self, style: Style) {
        self.fg = style.fg;
        self.bg = style.bg;
        self.modifier = style.modifier;
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub struct Rect {
    pub x: u16,
    pub y: u16,
    pub width: u16,
    pub height: u16,
}

impl Rect {
    pub fn new(x: u16, y: u16, width: u16, height: u16) -> Rect {
        Rect { x, y, width, height }
    }
    pub fn right(self) -> u16 {
        self.x.saturating_add(self.width)
    }
    pub fn bottom(self) -> u16 {
        self.y.saturating_add(self.height)
    }
    pub fn area(self) -> u16 {
        self.width.saturating_mul(self.height)
    }
    pub fn inner(self, margin: u16) -> Rect {
        if self.width < 2 * margin || self.height < 2 * margin {
            Rect::default()
        } else {
            Rect::new(self.x + margin, self.y + margin, self.width - 2 * margin, self.height - 2 * margin)
        }
    }
}

/// Width of a grapheme-ish symbol as used for layouting (tabs occupy one cell).
pub fn sym_width(s: &str) -> usize {
    let w = s.width();
    if w == 0 && !s.is_empty() {
        // control characters and zero-width symbols still occupy a cell when
        // written straight to the terminal
        if s.chars().all(|c| c.is_control()) {
            return 1;
        }
    }
    w
}

pub struct Buffer {
    pub area: Rect,
    pub content: Vec<Cell>,
}

impl Buffer {
    pub fn empty(area: Rect) -> Buffer {
        let n = area.area() as usize;
        Buffer { area, content: vec![Cell::default(); n] }
    }

    pub fn reset(&mut self) {
        for c in self.content.iter_mut() {
            *c = Cell::default();
        }
    }

    pub fn index_of(&self, x: u16, y: u16) -> usize {
        ((y - self.area.y) as usize) * (self.area.width as usize) + (x - self.area.x) as usize
    }

    pub fn get_mut(&mut self, x: u16, y: u16) -> Option<&mut Cell> {
        if x < self.area.x || y < self.area.y || x >= self.area.right() || y >= self.area.bottom() {
            return None;
        }
        let i = self.index_of(x, y);
        self.content.get_mut(i)
    }

    pub fn set_cell(&mut self, x: u16, y: u16, symbol: &str, style: Style) {
        if let Some(c) = self.get_mut(x, y) {
            c.set_symbol(symbol);
            c.set_style(style);
        }
    }

    /// Writes a string at (x, y) clipped to `max_width` cells, returns the
    /// x position after the last written cell.
    pub fn set_stringn(&mut self, x: u16, y: u16, s: &str, max_width: usize, style: Style) -> u16 {
        let mut cx = x;
        let end = (x as usize + max_width).min(self.area.right() as usize) as u16;
        for ch in s.chars() {
            let mut sym = String::new();
            sym.push(ch);
            let w = sym_width(&sym);
            if w == 0 {
                continue;
            }
            if (cx as usize) + w > end as usize {
                break;
            }
            if let Some(c) = self.get_mut(cx, y) {
                c.set_symbol(&sym);
                c.set_style(style);
            }
            // reset the cells covered by a wide symbol
            for i in 1..w {
                if let Some(c) = self.get_mut(cx + i as u16, y) {
                    c.set_symbol("");
                    c.set_style(style);
                }
            }
            cx += w as u16;
        }
        cx
    }

    pub fn set_string(&mut self, x: u16, y: u16, s: &str, style: Style) -> u16 {
        self.set_stringn(x, y, s, usize::MAX, style)
    }

    pub fn set_style(&mut self, area: Rect, style: Style) {
        for y in area.y..area.bottom() {
            for x in area.x..area.right() {
                if let Some(c) = self.get_mut(x, y) {
                    c.set_style(style);
                }
            }
        }
    }

    /// Compute the cells that differ from `previous`.
    pub fn diff<'a>(&self, previous: &'a Buffer) -> Vec<(u16, u16, &'a Cell)> {
        // NOTE: returns references into `previous`'s successor (self) – we
        // return cells of `self` so lifetimes are tied to self.
        unreachable!("use Buffer::diff_cells")
    }

    pub fn diff_cells(&self, previous: &Buffer) -> Vec<(u16, u16, Cell)> {
        let width = self.area.width as usize;
        let mut updates = Vec::new();
        let mut invalidated: usize = 0;
        let mut to_skip: usize = 0;
        for (i, (current, prev)) in self.content.iter().zip(previous.content.iter()).enumerate() {
            if (current != prev || invalidated > 0) && to_skip == 0 {
                let x = (i % width) as u16 + self.area.x;
                let y = (i / width) as u16 + self.area.y;
                updates.push((x, y, current.clone()));
            }
            let cw = sym_width(&current.symbol);
            to_skip = cw.saturating_sub(1);
            let affected = cw.max(sym_width(&prev.symbol));
            invalidated = affected.max(invalidated).saturating_sub(1);
        }
        updates
    }
}

/// Simple double-buffered terminal writing to stderr.
pub struct Terminal {
    buffers: [Buffer; 2],
    current: usize,
    pub cursor: Option<(u16, u16)>,
    hidden_cursor: bool,
    out: io::Stderr,
}

impl Terminal {
    pub fn new() -> io::Result<Terminal> {
        let (w, h) = terminal::size()?;
        let area = Rect::new(0, 0, w, h);
        Ok(Terminal {
            buffers: [Buffer::empty(area), Buffer::empty(area)],
            current: 0,
            cursor: None,
            hidden_cursor: false,
            out: io::stderr(),
        })
    }

    pub fn size(&self) -> Rect {
        self.buffers[self.current].area
    }

    fn autoresize(&mut self) -> io::Result<()> {
        let (w, h) = terminal::size()?;
        let area = Rect::new(0, 0, w, h);
        if area != self.buffers[self.current].area {
            self.buffers[0] = Buffer::empty(area);
            self.buffers[1] = Buffer::empty(area);
            queue!(self.out, terminal::Clear(terminal::ClearType::All))?;
        }
        Ok(())
    }

    pub fn draw<F: FnOnce(&mut Buffer) -> Option<(u16, u16)>>(&mut self, f: F) -> io::Result<()> {
        self.autoresize()?;
        let area = self.buffers[self.current].area;
        self.buffers[self.current].reset();
        let cursor = f(&mut self.buffers[self.current]);
        let _ = area;
        let updates = self.buffers[self.current].diff_cells(&self.buffers[1 - self.current]);
        self.flush_updates(&updates)?;
        match cursor {
            None => {
                queue!(self.out, Hide)?;
                self.hidden_cursor = true;
            }
            Some((x, y)) => {
                queue!(self.out, Show)?;
                queue!(self.out, MoveTo(x, y))?;
                self.hidden_cursor = false;
            }
        }
        self.current = 1 - self.current;
        self.out.flush()
    }

    fn flush_updates(&mut self, updates: &[(u16, u16, Cell)]) -> io::Result<()> {
        let mut fg = Color::Reset;
        let mut bg = Color::Reset;
        let mut modifier = Modifier::NONE;
        let mut last_pos: Option<(u16, u16)> = None;
        for (x, y, cell) in updates {
            let (x, y) = (*x, *y);
            if !matches!(last_pos, Some(p) if x == p.0 + 1 && y == p.1) {
                queue!(self.out, MoveTo(x, y))?;
            }
            last_pos = Some((x, y));
            if cell.modifier != modifier {
                write_modifier_diff(&mut self.out, modifier, cell.modifier)?;
                modifier = cell.modifier;
            }
            if cell.fg != fg || cell.bg != bg {
                queue!(self.out, SetColors(Colors::new(cell.fg.to_crossterm(), cell.bg.to_crossterm())))?;
                fg = cell.fg;
                bg = cell.bg;
            }
            queue!(self.out, Print(&cell.symbol))?;
        }
        queue!(
            self.out,
            SetColors(Colors::new(CColor::Reset, CColor::Reset)),
            SetAttribute(Attribute::Reset)
        )?;
        Ok(())
    }
}

fn write_modifier_diff<W: Write>(w: &mut W, from: Modifier, to: Modifier) -> io::Result<()> {
    let removed = from.difference(to);
    if removed.contains(Modifier::REVERSED) {
        queue!(w, SetAttribute(Attribute::NoReverse))?;
    }
    if removed.contains(Modifier::BOLD) {
        queue!(w, SetAttribute(Attribute::NormalIntensity))?;
        if to.contains(Modifier::DIM) {
            queue!(w, SetAttribute(Attribute::Dim))?;
        }
    }
    if removed.contains(Modifier::ITALIC) {
        queue!(w, SetAttribute(Attribute::NoItalic))?;
    }
    if removed.contains(Modifier::UNDERLINED) {
        queue!(w, SetAttribute(Attribute::NoUnderline))?;
    }
    if removed.contains(Modifier::DIM) {
        queue!(w, SetAttribute(Attribute::NormalIntensity))?;
    }
    if removed.contains(Modifier::CROSSED_OUT) {
        queue!(w, SetAttribute(Attribute::NotCrossedOut))?;
    }
    if removed.contains(Modifier::SLOW_BLINK) || removed.contains(Modifier::RAPID_BLINK) {
        queue!(w, SetAttribute(Attribute::NoBlink))?;
    }
    if removed.contains(Modifier::HIDDEN) {
        queue!(w, SetAttribute(Attribute::NoHidden))?;
    }
    let added = to.difference(from);
    if added.contains(Modifier::REVERSED) {
        queue!(w, SetAttribute(Attribute::Reverse))?;
    }
    if added.contains(Modifier::BOLD) {
        queue!(w, SetAttribute(Attribute::Bold))?;
    }
    if added.contains(Modifier::ITALIC) {
        queue!(w, SetAttribute(Attribute::Italic))?;
    }
    if added.contains(Modifier::UNDERLINED) {
        queue!(w, SetAttribute(Attribute::Underlined))?;
    }
    if added.contains(Modifier::DIM) {
        queue!(w, SetAttribute(Attribute::Dim))?;
    }
    if added.contains(Modifier::CROSSED_OUT) {
        queue!(w, SetAttribute(Attribute::CrossedOut))?;
    }
    if added.contains(Modifier::SLOW_BLINK) {
        queue!(w, SetAttribute(Attribute::SlowBlink))?;
    }
    if added.contains(Modifier::RAPID_BLINK) {
        queue!(w, SetAttribute(Attribute::RapidBlink))?;
    }
    if added.contains(Modifier::HIDDEN) {
        queue!(w, SetAttribute(Attribute::Hidden))?;
    }
    Ok(())
}

// ---------------------------------------------------------------------------
// drawing helpers

/// Draws a box with borders around `area` with a title, returns the inner area.
pub fn draw_block(buf: &mut Buffer, area: Rect, title: &str, title_style: Style) -> Rect {
    if area.width == 0 || area.height == 0 {
        return Rect::default();
    }
    let st = Style::default();
    let right = area.right() - 1;
    let bottom = area.bottom() - 1;
    // corners / sides
    for y in area.y..area.bottom() {
        buf.set_cell(area.x, y, "│", st);
        if area.width > 1 {
            buf.set_cell(right, y, "│", st);
        }
    }
    for x in area.x..area.right() {
        buf.set_cell(x, area.y, "─", st);
        if area.height > 1 {
            buf.set_cell(x, bottom, "─", st);
        }
    }
    buf.set_cell(area.x, area.y, "┌", st);
    if area.width > 1 {
        buf.set_cell(right, area.y, "┐", st);
    }
    if area.height > 1 {
        buf.set_cell(area.x, bottom, "└", st);
        if area.width > 1 {
            buf.set_cell(right, bottom, "┘", st);
        }
    }
    // title
    if area.width > 2 {
        let max = (area.width - 2) as usize;
        buf.set_stringn(area.x + 1, area.y, title, max, title_style);
    }
    area.inner(1)
}

/// A styled run of text.
#[derive(Clone, Debug)]
pub struct Span {
    pub text: String,
    pub style: Style,
}

impl Span {
    pub fn raw<S: Into<String>>(s: S) -> Span {
        Span { text: s.into(), style: Style::default() }
    }
    pub fn styled<S: Into<String>>(s: S, style: Style) -> Span {
        Span { text: s.into(), style }
    }
}

/// Draws lines of spans into `area`, truncating lines that are too long.
pub fn draw_lines(buf: &mut Buffer, area: Rect, lines: &[Vec<Span>]) {
    for (i, line) in lines.iter().enumerate() {
        if i as u16 >= area.height {
            break;
        }
        let y = area.y + i as u16;
        let mut x = area.x;
        let end = area.right();
        'outer: for span in line {
            for ch in span.text.chars() {
                let mut sym = String::new();
                sym.push(ch);
                let w = sym_width(&sym);
                if w == 0 {
                    continue;
                }
                if (x as usize) + w > end as usize {
                    break 'outer;
                }
                if let Some(c) = buf.get_mut(x, y) {
                    c.set_symbol(&sym);
                    c.set_style(span.style);
                }
                for k in 1..w {
                    if let Some(c) = buf.get_mut(x + k as u16, y) {
                        c.set_symbol("");
                        c.set_style(span.style);
                    }
                }
                x += w as u16;
            }
        }
    }
}

/// Draws a text line right aligned within area (single row).
pub fn draw_right_aligned(buf: &mut Buffer, area: Rect, text: &str, style: Style) {
    if area.height == 0 {
        return;
    }
    let w = text.width() as u16;
    let x = if w >= area.width { area.x } else { area.x + area.width - w };
    buf.set_stringn(x, area.y, text, area.width as usize, style);
}
EOF
