//! Multi-line text input state.

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Input {
    pub lines: Vec<String>,
    /// line index of the cursor
    pub line: usize,
    /// character index of the cursor within the line
    pub col: usize,
}

impl Default for Input {
    fn default() -> Self {
        Input { lines: vec![String::new()], line: 0, col: 0 }
    }
}

fn char_len(s: &str) -> usize {
    s.chars().count()
}

fn byte_idx(s: &str, col: usize) -> usize {
    s.char_indices().nth(col).map(|(i, _)| i).unwrap_or(s.len())
}

impl Input {
    pub fn new() -> Input {
        Input::default()
    }

    pub fn from_lines(lines: Vec<String>) -> Input {
        let lines = if lines.is_empty() { vec![String::new()] } else { lines };
        let line = lines.len() - 1;
        let col = char_len(&lines[line]);
        Input { lines, line, col }
    }

    pub fn from_text(text: &str) -> Input {
        Input::from_lines(text.lines().map(|l| l.to_string()).collect())
    }

    pub fn set_text(&mut self, text: &str) {
        *self = Input::from_text(text);
    }

    pub fn set_lines(&mut self, lines: Vec<String>) {
        *self = Input::from_lines(lines);
    }

    /// Full content, lines joined by newlines.
    pub fn content(&self) -> String {
        self.lines.join("\n")
    }

    pub fn is_empty(&self) -> bool {
        self.lines.iter().all(|l| l.is_empty())
    }

    pub fn current_line(&self) -> &str {
        &self.lines[self.line]
    }

    fn clamp(&mut self) {
        let len = char_len(&self.lines[self.line]);
        if self.col > len {
            self.col = len;
        }
    }

    pub fn clear(&mut self) {
        *self = Input::default();
    }

    pub fn insert_char(&mut self, c: char) {
        let i = byte_idx(&self.lines[self.line], self.col);
        self.lines[self.line].insert(i, c);
        self.col += 1;
    }

    pub fn insert_str(&mut self, s: &str) {
        for c in s.chars() {
            if c == '\n' {
                self.newline();
            } else {
                self.insert_char(c);
            }
        }
    }

    pub fn newline(&mut self) {
        let i = byte_idx(&self.lines[self.line], self.col);
        let rest = self.lines[self.line].split_off(i);
        self.lines.insert(self.line + 1, rest);
        self.line += 1;
        self.col = 0;
    }

    pub fn backspace(&mut self) {
        if self.col > 0 {
            let i = byte_idx(&self.lines[self.line], self.col - 1);
            self.lines[self.line].remove(i);
            self.col -= 1;
        } else if self.line > 0 {
            let cur = self.lines.remove(self.line);
            self.line -= 1;
            self.col = char_len(&self.lines[self.line]);
            self.lines[self.line].push_str(&cur);
        }
    }

    pub fn delete(&mut self) {
        let len = char_len(&self.lines[self.line]);
        if self.col < len {
            let i = byte_idx(&self.lines[self.line], self.col);
            self.lines[self.line].remove(i);
        } else if self.line + 1 < self.lines.len() {
            let next = self.lines.remove(self.line + 1);
            self.lines[self.line].push_str(&next);
        }
    }

    /// Deletes backwards until (and including) the previous space.
    pub fn delete_word(&mut self) {
        loop {
            let line = &mut self.lines[self.line];
            if line.is_empty() {
                break;
            }
            let idx = self.col.saturating_sub(1);
            let bi = byte_idx(line, idx);
            if bi >= line.len() {
                break;
            }
            let removed = line.remove(bi);
            self.col = self.col.saturating_sub(1);
            if removed == ' ' || self.col == 0 {
                break;
            }
        }
    }

    pub fn left(&mut self) {
        if self.col > 0 {
            self.col -= 1;
        } else if self.line > 0 {
            self.line -= 1;
            self.col = char_len(&self.lines[self.line]);
        }
    }

    pub fn right(&mut self) {
        if self.col < char_len(&self.lines[self.line]) {
            self.col += 1;
        } else if self.line + 1 < self.lines.len() {
            self.line += 1;
            self.col = 0;
        }
    }

    pub fn up(&mut self) {
        if self.line > 0 {
            self.line -= 1;
            self.clamp();
        }
    }

    pub fn down(&mut self) {
        if self.line + 1 < self.lines.len() {
            self.line += 1;
            self.clamp();
        }
    }

    pub fn home(&mut self) {
        self.col = 0;
    }

    pub fn end(&mut self) {
        self.col = char_len(&self.lines[self.line]);
    }

    /// Byte index of the cursor in the current line.
    pub fn cursor_byte_idx(&self) -> usize {
        byte_idx(&self.lines[self.line], self.col)
    }

    /// Returns the whitespace delimited token around the cursor in the current
    /// line together with its byte range.
    pub fn word_under_cursor(&self) -> (std::ops::Range<usize>, String) {
        let line = &self.lines[self.line];
        let ci = self.cursor_byte_idx();
        let start = line[..ci].rfind(char::is_whitespace).map(|i| i + line[i..].chars().next().unwrap().len_utf8()).unwrap_or(0);
        let end = line[ci..].find(char::is_whitespace).map(|i| ci + i).unwrap_or(line.len());
        (start..end, line[start..end].to_string())
    }

    /// Replaces the given byte range of the current line with `replacement`
    /// and puts the cursor behind the inserted text.
    pub fn replace_range(&mut self, range: std::ops::Range<usize>, replacement: &str) {
        let line = &mut self.lines[self.line];
        line.replace_range(range.clone(), replacement);
        let new_byte = range.start + replacement.len();
        self.col = line[..new_byte].chars().count();
    }

    /// The byte index of the cursor in the content joined with single spaces.
    pub fn joined_cursor_idx(&self) -> usize {
        let mut idx = 0;
        for (i, l) in self.lines.iter().enumerate() {
            if i == self.line {
                idx += self.cursor_byte_idx();
                break;
            }
            idx += l.len() + 1;
        }
        idx
    }
}
