            7 => style.modifier.insert(Modifier::REVERSED),
            8 => style.modifier.insert(Modifier::HIDDEN),
            9 => style.modifier.insert(Modifier::CROSSED_OUT),
            22 => {
                style.modifier.remove(Modifier::BOLD);
                style.modifier.remove(Modifier::DIM);
            }
            23 => style.modifier.remove(Modifier::ITALIC),
            24 => style.modifier.remove(Modifier::UNDERLINED),
            25 => {
                style.modifier.remove(Modifier::SLOW_BLINK);
                style.modifier.remove(Modifier::RAPID_BLINK);
            }
            27 => style.modifier.remove(Modifier::REVERSED),
            28 => style.modifier.remove(Modifier::HIDDEN),
            29 => style.modifier.remove(Modifier::CROSSED_OUT),
            30..=37 => style.fg = basic_color(p - 30),
            90..=97 => style.fg = basic_color(p - 90 + 8),
            40..=47 => style.bg = basic_color(p - 40),
            100..=107 => style.bg = basic_color(p - 100 + 8),
            39 => style.fg = Color::Reset,
            49 => style.bg = Color::Reset,
            38 | 48 => {
                let mut color = None;
                if i + 1 < params.len() {
                    match params[i + 1] {
                        5 => {
                            if i + 2 < params.len() {
                                color = Some(Color::Indexed(params[i + 2].min(255) as u8));
                                i += 2;
                            } else {
                                i += 1;
                            }
                        }
                        2 => {
                            if i + 4 < params.len() {
                                color = Some(Color::Rgb(
                                    params[i + 2].min(255) as u8,
                                    params[i + 3].min(255) as u8,
                                    params[i + 4].min(255) as u8,
                                ));
                                i += 4;
                            } else {
                                i = params.len();
                            }
                        }
                        _ => {}
                    }
                }
                if let Some(c) = color {
                    if p == 38 {
                        style.fg = c;
                    } else {
                        style.bg = c;
                    }
                }
            }
            _ => {}
        }
        i += 1;
    }
}

/// Parses `text` into styled lines (same line semantics as `str::lines`).
pub fn parse(text: &str) -> Vec<Vec<Span>> {
    let mut lines: Vec<Vec<Span>> = Vec::new();
    let mut cur_line: Vec<Span> = Vec::new();
    let mut cur_text = String::new();
    let mut style = Style::default();
    let mut ended_with_newline = false;

    let chars: Vec<char> = text.chars().collect();
    let mut i = 0;

    fn flush(cur_line: &mut Vec<Span>, cur_text: &mut String, style: Style) {
        if !cur_text.is_empty() {
            cur_line.push(Span::styled(std::mem::take(cur_text), style));
        }
    }

    while i < chars.len() {
        let c = chars[i];
        if c == '\x1b' {
            // escape sequence
            if i + 1 < chars.len() && chars[i + 1] == '[' {
                let mut j = i + 2;
                let mut params_str = String::new();
                while j < chars.len() && (chars[j].is_ascii_digit() || chars[j] == ';' || chars[j] == '?' || chars[j] == ':') {
                    params_str.push(chars[j]);
                    j += 1;
                }
                if j < chars.len() {
                    let final_byte = chars[j];
                    if final_byte == 'm' && !params_str.contains('?') {
                        let params: Vec<u16> = if params_str.is_empty() {
                            Vec::new()
                        } else {
                            params_str
                                .split(|c| c == ';' || c == ':')
                                .map(|p| p.parse::<u16>().unwrap_or(0))
                                .collect()
                        };
                        flush(&mut cur_line, &mut cur_text, style);
                        apply_sgr(&mut style, &params);
                    }
                    i = j + 1;
                } else {
                    i = j;
                }
                continue;
            } else {
                // other escape: skip ESC and following char
                i += 2;
                continue;
            }
        }
        if c == '\n' {
            flush(&mut cur_line, &mut cur_text, style);
            lines.push(std::mem::take(&mut cur_line));
            ended_with_newline = true;
            i += 1;
            continue;
        }
        if c == '\r' {
            // part of CRLF line endings -> drop
            if i + 1 < chars.len() && chars[i + 1] == '\n' {
                i += 1;
                continue;
            }
        }
        ended_with_newline = false;
        cur_text.push(c);
        i += 1;
    }
    flush(&mut cur_line, &mut cur_text, style);
    if !cur_line.is_empty() || (!ended_with_newline && !text.is_empty()) {
        lines.push(cur_line);
    }
    lines
}
