//! A small shell syntax highlighter producing base16-ocean like colors.

use crate::tui::{Color, Span, Style};

pub const TEXT: Color = Color::Rgb(192, 197, 206);
pub const COMMENT: Color = Color::Rgb(101, 115, 126);
pub const BUILTIN: Color = Color::Rgb(150, 181, 180);
pub const COMMAND: Color = Color::Rgb(143, 161, 179);
pub const KEYWORD: Color = Color::Rgb(180, 142, 173);
pub const VARIABLE: Color = Color::Rgb(191, 97, 106);
pub const STRING: Color = Color::Rgb(163, 190, 140);
pub const NUMBER: Color = Color::Rgb(208, 135, 112);

const KEYWORDS: &[&str] = &[
    "if", "then", "else", "elif", "fi", "for", "while", "until", "do", "done", "case", "esac", "function",
    "export", "local", "declare", "readonly", "typeset", "break", "continue", "return",
];

const DECLARE_KEYWORDS: &[&str] = &["export", "local", "declare", "readonly", "typeset"];

const BUILTINS: &[&str] = &[
    ".", ":", "alias", "bg", "bind", "builtin", "caller", "cd", "command", "disown", "echo", "enable", "eval",
    "exec", "exit", "fg", "getopts", "hash", "help", "jobs", "kill", "let", "logout", "mapfile", "printf", "pwd",
    "read", "readarray", "set", "shift", "shopt", "source", "suspend", "times", "trap", "type", "ulimit", "umask",
    "unalias", "unset", "wait", "[", "[[",
];

/// Commands for which generic `-x` options are not highlighted.
const NO_OPTION_CMDS: &[&str] = &[
    "exit", "shift", "source", ".", "eval", "let", "fg", "bg", "builtin", "logout", "times", "getopts", "caller",
    "return", "continue", "kill", "jobs", "shopt", "disown", ":",
];

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum ArgMode {
    /// expecting a command name
    CmdStart,
    /// normal arguments of a command
    Args,
    /// arguments of export/local/declare/...
    Declare,
    /// word list after `in`
    List,
    /// the variable name after `for`
    ForVar,
    /// expecting the `in` keyword
    ExpectIn,
    /// name after `function`
    FuncName,
}

struct Hl {
    chars: Vec<char>,
    colors: Vec<Color>,
}

fn is_word_char_end(c: char) -> bool {
    c.is_whitespace() || matches!(c, ';' | '|' | '&' | '(' | ')' | '<' | '>' | '\'' | '"' | '`' | '$')
}

fn is_ident_start(c: char) -> bool {
    c.is_ascii_alphabetic() || c == '_'
}

fn is_ident_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_'
}

impl Hl {
    fn set(&mut self, i: usize, c: Color) {
        if i < self.colors.len() {
            self.colors[i] = c;
        }
    }

    fn set_range(&mut self, from: usize, to: usize, c: Color) {
        for i in from..to.min(self.colors.len()) {
            self.colors[i] = c;
        }
    }

    fn at(&self, i: usize) -> Option<char> {
        self.chars.get(i).copied()
    }

    fn starts_with(&self, i: usize, s: &str) -> bool {
        let mut j = i;
        for c in s.chars() {
            if self.at(j) != Some(c) {
                return false;
            }
            j += 1;
        }
        true
    }

    /// Scans a run of word characters starting at `i` (handling escapes),
    /// returns the end index. Escapes are colored immediately.
    fn scan_word(&mut self, mut i: usize, escape_color: Color) -> (usize, String) {
        let mut word = String::new();
        while let Some(c) = self.at(i) {
            if c == '\\' {
                if let Some(n) = self.at(i + 1) {
                    self.set(i, escape_color);
                    self.set(i + 1, escape_color);
                    word.push(n);
                    i += 2;
                    continue;
                } else {
                    self.set(i, escape_color);
                    i += 1;
                    break;
                }
            }
            if is_word_char_end(c) {
                break;
            }
            word.push(c);
            i += 1;
        }
        (i, word)
    }

    /// Colors the plain (non escape) chars of the word range [from, to).
    fn color_word(&mut self, from: usize, to: usize, color: Color) {
        let mut i = from;
        while i < to {
            if self.at(i) == Some('\\') {
                i += 2;
                continue;
            }
            self.set(i, color);
            i += 1;
        }
    }

    fn single_quoted(&mut self, mut i: usize) -> usize {
        self.set(i, TEXT);
        i += 1;
        while let Some(c) = self.at(i) {
            if c == '\'' {
                self.set(i, TEXT);
                return i + 1;
            }
            self.set(i, STRING);
            i += 1;
        }
        i
    }

    fn arithmetic(&mut self, mut i: usize, paren_color: Color) -> usize {
        // i points after "$(("
        while let Some(c) = self.at(i) {
            if self.starts_with(i, "))") {
                self.set(i, paren_color);
                self.set(i + 1, paren_color);
                return i + 2;
            }
            if c.is_ascii_digit() {
                self.set(i, NUMBER);
            } else {
                self.set(i, TEXT);
            }
            i += 1;
        }
        i
    }

    fn dollar(&mut self, i: usize, in_dquote: bool) -> usize {
        let wrap = if in_dquote { STRING } else { TEXT };
        self.set(i, TEXT);
        let mut j = i + 1;
        if self.starts_with(j, "((") {
            self.set(j, wrap);
            self.set(j + 1, wrap);
            return self.arithmetic(j + 2, wrap);
        }
        match self.at(j) {
            Some('(') => {
                self.set(j, wrap);
                let end = self.scan(j + 1, Some(')'));
                if self.at(end) == Some(')') {
                    self.set(end, wrap);
                    return end + 1;
                }
                return end;
            }
            Some('{') => {
                self.set(j, wrap);
                j += 1;
                if matches!(self.at(j), Some('#') | Some('!')) {
                    self.set(j, TEXT);
                    j += 1;
                }
                // name
                if let Some(c) = self.at(j) {
                    if is_ident_start(c) {
                        while let Some(c) = self.at(j) {
                            if !is_ident_char(c) {
                                break;
                            }
                            self.set(j, VARIABLE);
                            j += 1;
                        }
                    } else if c.is_ascii_digit() {
                        while let Some(c) = self.at(j) {
                            if !c.is_ascii_digit() {
                                break;
                            }
                            self.set(j, VARIABLE);
                            j += 1;
                        }
                    } else if matches!(c, '?' | '@' | '*' | '$' | '!' | '-') {
                        self.set(j, VARIABLE);
                        j += 1;
                    }
                }
                while let Some(c) = self.at(j) {
                    if c == '}' {
                        self.set(j, wrap);
                        return j + 1;
                    }
                    if c == '\n' && !in_dquote {
                        return j;
                    }
                    if in_dquote {
                        if matches!(c, ':' | '-' | '+' | '=' | '/' | '#' | '%' | '?') {
                            self.set(j, TEXT);
                        } else {
                            self.set(j, STRING);
                        }
                    } else {
                        self.set(j, TEXT);
                    }
                    j += 1;
                }
                j
            }
            Some(c) if is_ident_start(c) => {
                while let Some(c) = self.at(j) {
                    if !is_ident_char(c) {
                        break;
                    }
                    self.set(j, VARIABLE);
                    j += 1;
                }
                j
            }
            Some(c) if c.is_ascii_digit() || matches!(c, '?' | '#' | '@' | '*' | '$' | '!' | '-') => {
                self.set(j, VARIABLE);
                j + 1
            }
            _ => j,
        }
    }

    fn double_quoted(&mut self, mut i: usize) -> usize {
        self.set(i, TEXT);
        i += 1;
        while let Some(c) = self.at(i) {
            match c {
                '"' => {
                    self.set(i, TEXT);
                    return i + 1;
                }
                '\\' => {
                    if let Some(n) = self.at(i + 1) {
                        let col = if matches!(n, '$' | '"' | '\\' | '`') { BUILTIN } else { STRING };
                        self.set(i, col);
                        self.set(i + 1, col);
                        i += 2;
                    } else {
                        self.set(i, STRING);
                        i += 1;
                    }
                }
                '$' => {
                    i = self.dollar(i, true);
                }
                '`' => {
                    self.set(i, STRING);
                    let end = self.scan(i + 1, Some('`'));
                    if self.at(end) == Some('`') {
                        self.set(end, STRING);
                        i = end + 1;
                    } else {
                        i = end;
                    }
                }
                _ => {
                    self.set(i, STRING);
                    i += 1;
                }
            }
        }
        i
    }

    fn is_word_start(&self, i: usize) -> bool {
        if i == 0 {
            return true;
        }
        match self.at(i - 1) {
            Some(c) => c.is_whitespace() || matches!(c, ';' | '|' | '&' | '(' | '`'),
            None => true,
        }
    }

    fn follower_ok_for_keyword(&self, word: &str, end: usize, in_case: bool) -> bool {
        match self.at(end) {
            None | Some('\n') => matches!(word, "then" | "return") || (word == "esac" && in_case),
            Some(_) => true,
        }
    }

    fn follower_ok_for_builtin(&self, word: &str, end: usize) -> bool {
        match self.at(end) {
            None | Some('\n') => word != "alias",
            Some(c) if c.is_whitespace() => true,
            Some(';') | Some('|') | Some('>') | Some('<') => word != "alias",
            Some(_) => false,
        }
    }

    /// Scans a command list until `end_on` (not consumed) or the end of text.
    fn scan(&mut self, mut i: usize, end_on: Option<char>) -> usize {
        let mut mode = ArgMode::CmdStart;
        let mut cmd_name: Option<String> = None;
        let mut in_case = false;
        let mut case_pattern = false;
        let mut after_redirect_amp = false;
        let mut heredoc_tag = false;

        while let Some(c) = self.at(i) {
            if end_on == Some(c) {
                return i;
            }
            if after_redirect_amp && c.is_ascii_digit() {
                while let Some(d) = self.at(i) {
                    if !d.is_ascii_digit() {
                        break;
                    }
                    self.set(i, NUMBER);
                    i += 1;
                }
                after_redirect_amp = false;
                continue;
            }
            after_redirect_amp = false;
            match c {
                '\n' => {
                    self.set(i, TEXT);
                    i += 1;
                    mode = ArgMode::CmdStart;
                    cmd_name = None;
                }
                c if c.is_whitespace() => {
                    self.set(i, TEXT);
                    i += 1;
                }
                '#' if self.is_word_start(i) => {
                    while let Some(c) = self.at(i) {
                        if c == '\n' {
                            break;
                        }
                        self.set(i, COMMENT);
                        i += 1;
                    }
                }
                '\'' => {
                    i = self.single_quoted(i);
                    if mode == ArgMode::CmdStart {
                        mode = ArgMode::Args;
                    }
                }
                '"' => {
                    i = self.double_quoted(i);
                    if mode == ArgMode::CmdStart {
                        mode = ArgMode::Args;
                    }
                }
                '`' => {
                    self.set(i, TEXT);
                    let end = self.scan(i + 1, Some('`'));
                    if self.at(end) == Some('`') {
                        self.set(end, TEXT);
                        i = end + 1;
                    } else {
                        i = end;
                    }
                    if mode == ArgMode::CmdStart {
                        mode = ArgMode::Args;
                    }
                }
                '$' => {
                    i = self.dollar(i, false);
                    if mode == ArgMode::CmdStart {
                        mode = ArgMode::Args;
                    } else if mode == ArgMode::ExpectIn {
                        // case expression done
                    }
                }
                ';' => {
                    self.set(i, TEXT);
                    i += 1;
                    if self.at(i) == Some(';') {
                        self.set(i, TEXT);
                        i += 1;
                        if in_case {
                            case_pattern = true;
                        }
                    }
                    mode = ArgMode::CmdStart;
                    cmd_name = None;
                }
                '|' => {
                    self.set(i, TEXT);
                    i += 1;
                    if matches!(self.at(i), Some('|') | Some('&')) {
                        self.set(i, TEXT);
                        i += 1;
                    }
                    mode = ArgMode::CmdStart;
                    cmd_name = None;
                }
                '&' => {
                    self.set(i, TEXT);
                    i += 1;
                    if self.at(i) == Some('&') {
                        self.set(i, TEXT);
                        i += 1;
                        mode = ArgMode::CmdStart;
                        cmd_name = None;
                    } else if self.at(i) == Some('>') {
                        self.set(i, TEXT);
                        i += 1;
                        if self.at(i) == Some('>') {
                            self.set(i, TEXT);
                            i += 1;
                        }
                    } else {
                        mode = ArgMode::CmdStart;
                        cmd_name = None;
                    }
                }
                '(' => {
                    self.set(i, TEXT);
                    let end = self.scan(i + 1, Some(')'));
                    if self.at(end) == Some(')') {
                        self.set(end, TEXT);
                        i = end + 1;
                    } else {
                        i = end;
                    }
                    if mode == ArgMode::CmdStart {
                        mode = ArgMode::Args;
                    }
                }
                ')' => {
                    if case_pattern {
                        self.set(i, KEYWORD);
                        case_pattern = false;
                        mode = ArgMode::CmdStart;
                        cmd_name = None;
                    } else {
                        self.set(i, TEXT);
                    }
                    i += 1;
                }
                '<' | '>' => {
                    self.set(i, TEXT);
                    let first = c;
                    i += 1;
                    match self.at(i) {
                        Some('<') if first == '<' => {
                            self.set(i, TEXT);
                            i += 1;
                            if self.at(i) == Some('<') {
                                self.set(i, TEXT);
                                i += 1;
                            } else {
                                heredoc_tag = true;
                            }
                        }
                        Some('>') if first == '>' => {
                            self.set(i, TEXT);
                            i += 1;
                        }
                        Some('&') => {
                            self.set(i, TEXT);
                            i += 1;
                            after_redirect_amp = true;
                        }
                        Some('|') if first == '>' => {
                            self.set(i, TEXT);
                            i += 1;
                        }
                        Some('(') => {
                            self.set(i, TEXT);
                            let end = self.scan(i + 1, Some(')'));
                            if self.at(end) == Some(')') {
                                self.set(end, TEXT);
                                i = end + 1;
                            } else {
                                i = end;
                            }
                        }
                        _ => {}
                    }
                    if mode == ArgMode::CmdStart {
                        // a redirection before the command name: keep expecting one
                    }
                }
                _ => {
                    // a word
                    let start = i;
                    let (end, word) = self.scan_word(i, BUILTIN);
                    if end == start {
                        // should not happen, avoid infinite loop
                        self.set(i, TEXT);
                        i += 1;
                        continue;
                    }
                    i = end;
                    if heredoc_tag {
                        self.color_word(start, end, KEYWORD);
                        heredoc_tag = false;
                        continue;
                    }
                    // number directly before a redirection
                    if !word.is_empty()
                        && word.chars().all(|c| c.is_ascii_digit())
                        && matches!(self.at(end), Some('<') | Some('>'))
                    {
                        self.color_word(start, end, NUMBER);
                        continue;
                    }
                    match mode {
                        ArgMode::CmdStart => {
                            if word == "{" || word == "}" {
                                self.color_word(start, end, TEXT);
                                continue;
                            }
                            if let Some(eq) = word.find('=') {
                                let name = &word[..eq];
                                if !name.is_empty()
                                    && is_ident_start(name.chars().next().unwrap())
                                    && name.chars().all(|c| is_ident_char(c) || c == '.')
                                {
                                    self.color_assignment(start, end, eq);
                                    continue;
                                }
                            }
                            if KEYWORDS.contains(&word.as_str())
                                && self.follower_ok_for_keyword(&word, end, in_case)
                            {
                                self.color_word(start, end, KEYWORD);
                                match word.as_str() {
                                    "for" => mode = ArgMode::ForVar,
                                    "case" => {
                                        mode = ArgMode::ExpectIn;
                                        in_case = true;
                                    }
                                    "function" => mode = ArgMode::FuncName,
                                    "esac" => {
                                        in_case = false;
                                        mode = ArgMode::Args;
                                    }
                                    "fi" | "done" => mode = ArgMode::Args,
                                    "break" | "continue" | "return" => {
                                        mode = ArgMode::Args;
                                        cmd_name = Some(word.clone());
                                    }
                                    w if DECLARE_KEYWORDS.contains(&w) => mode = ArgMode::Declare,
                                    _ => mode = ArgMode::CmdStart,
                                }
                                continue;
                            }
                            if BUILTINS.contains(&word.as_str()) && self.follower_ok_for_builtin(&word, end) {
                                self.color_word(start, end, BUILTIN);
                                cmd_name = Some(word.clone());
                                mode = ArgMode::Args;
                                continue;
                            }
                            // generic command name
                            if word.starts_with('~') {
                                self.set(start, VARIABLE);
                                self.color_word(start + 1, end, COMMAND);
                            } else {
                                self.color_word(start, end, COMMAND);
                            }
                            cmd_name = Some(word.clone());
                            mode = ArgMode::Args;
                        }
                        ArgMode::ForVar => {
                            self.color_word(start, end, TEXT);
                            mode = ArgMode::ExpectIn;
                        }
                        ArgMode::FuncName => {
                            self.color_word(start, end, COMMAND);
                            mode = ArgMode::Args;
                        }
                        ArgMode::ExpectIn => {
                            if word == "in" {
                                self.color_word(start, end, KEYWORD);
                                if in_case {
                                    case_pattern = true;
                                    mode = ArgMode::Args;
                                } else {
                                    mode = ArgMode::List;
                                }
                            } else {
                                self.color_word(start, end, TEXT);
                            }
                        }
                        ArgMode::List => {
                            self.color_word(start, end, TEXT);
                        }
                        ArgMode::Declare => {
                            if word.starts_with('-') && word.len() > 1 {
                                self.color_option(start, end, &word);
                            } else if let Some(eq) = word.find('=') {
                                self.color_assignment(start, end, eq);
                            } else {
                                self.color_word(start, end, VARIABLE);
                            }
                        }
                        ArgMode::Args => {
                            if word == "]" || word == "]]" {
                                self.color_word(start, end, BUILTIN);
                            } else if word.starts_with('-') && self.option_allowed(&cmd_name, &word, end) {
                                self.color_option(start, end, &word);
                            } else if word == "~" || word.starts_with("~/") {
                                self.set(start, VARIABLE);
                                self.color_word(start + 1, end, TEXT);
                            } else {
                                self.color_word(start, end, TEXT);
                            }
                        }
                    }
                }
            }
        }
        i
    }

    fn option_allowed(&self, cmd_name: &Option<String>, word: &str, end: usize) -> bool {
        let dashes = word.chars().take_while(|c| *c == '-').count();
        if dashes > 2 || dashes == word.chars().count() {
            return false;
        }
        let after = word.chars().nth(dashes).unwrap();
        if !(after.is_ascii_alphanumeric() || after == '_') {
            return false;
        }
        match cmd_name.as_deref() {
            Some("echo") => word.len() > 1 && word[1..].chars().all(|c| matches!(c, 'n' | 'e' | 'E')),
            Some(c) if NO_OPTION_CMDS.contains(&c) => false,
            Some("[") | Some("[[") => matches!(self.at(end), Some(c) if c.is_whitespace()),
            _ => true,
        }
    }

    fn color_option(&mut self, start: usize, end: usize, word: &str) {
        // the `--?[A-Za-z0-9_-]+` prefix is highlighted, the rest is plain
        let mut n = 0;
        for c in word.chars() {
            if c.is_ascii_alphanumeric() || c == '_' || c == '-' {
                n += 1;
            } else {
                break;
            }
        }
        // map char count n to index in chars (escapes complicate; ignore)
        let mut i = start;
        let mut count = 0;
        while i < end {
            if self.at(i) == Some('\\') {
                i += 2;
                count += 1;
                continue;
            }
            if count < n {
                self.set(i, VARIABLE);
            } else {
                self.set(i, TEXT);
            }
            count += 1;
            i += 1;
        }
    }

    fn color_assignment(&mut self, start: usize, end: usize, eq: usize) {
        // `eq` is the char index of '=' within the word
        let mut i = start;
        let mut count = 0;
        while i < end {
            if self.at(i) == Some('\\') {
                i += 2;
                count += 1;
                continue;
            }
            if count < eq {
                self.set(i, VARIABLE);
            } else if count == eq {
                self.set(i, TEXT);
            } else {
                self.set(i, STRING);
            }
            count += 1;
            i += 1;
        }
    }
}

/// Highlights `text` (lines separated by '\n'), returning one list of spans per line.
pub fn highlight(text: &str) -> Vec<Vec<Span>> {
    let chars: Vec<char> = text.chars().collect();
    let mut hl = Hl { colors: vec![TEXT; chars.len()], chars };
    let mut i = 0;
    while i < hl.chars.len() {
        let end = hl.scan(i, None);
        if end >= hl.chars.len() {
            break;
        }
        // stray terminator char
        hl.set(end, TEXT);
        i = end + 1;
    }
    let mut lines: Vec<Vec<Span>> = Vec::new();
    let mut cur: Vec<Span> = Vec::new();
    let mut cur_text = String::new();
    let mut cur_color = TEXT;
    for (idx, c) in hl.chars.iter().enumerate() {
        if *c == '\n' {
            if !cur_text.is_empty() {
                cur.push(Span::styled(std::mem::take(&mut cur_text), Style::new().fg(cur_color)));
            }
            lines.push(std::mem::take(&mut cur));
            continue;
        }
        let col = hl.colors[idx];
        if col != cur_color && !cur_text.is_empty() {
            cur.push(Span::styled(std::mem::take(&mut cur_text), Style::new().fg(cur_color)));
        }
        cur_color = col;
        cur_text.push(*c);
    }
    if !cur_text.is_empty() {
        cur.push(Span::styled(cur_text, Style::new().fg(cur_color)));
    }
    lines.push(cur);
    lines
}

/// Plain (unhighlighted) lines.
pub fn plain(text: &str) -> Vec<Vec<Span>> {
    text.split('\n').map(|l| vec![Span::raw(l.to_string())]).collect()
}
