    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

/// Path of `target` relative to the current working directory.
fn relative_to_cwd(target: &Path) -> PathBuf {
    let cwd = match std::env::current_dir() {
        Ok(c) => c,
        Err(_) => return target.to_path_buf(),
    };
    let t: Vec<_> = target.components().collect();
    let c: Vec<_> = cwd.components().collect();
    let mut common = 0;
    while common < t.len() && common < c.len() && t[common] == c[common] {
        common += 1;
    }
    let mut result = PathBuf::new();
    for _ in common..c.len() {
        result.push("..");
    }
    for comp in &t[common..] {
        result.push(comp.as_os_str());
    }
    result
}

fn char_map(value: Option<&crate::toml::Value>) -> Option<HashMap<char, String>> {
    let table = value?.as_table()?;
    let mut map = HashMap::new();
    for (k, v) in table {
        let mut chars = k.chars();
        let c = chars.next()?;
        if chars.next().is_some() {
            return None;
        }
        let s = v.as_str()?;
        map.insert(c, s.to_string());
    }
    Some(map)
}

pub fn default_help_viewers() -> HashMap<char, String> {
    let mut m = HashMap::new();
    m.insert('m', "man ??".to_string());
    m.insert('h', "?? --help | less".to_string());
    m
}

pub fn default_output_viewers() -> HashMap<char, String> {
    let mut m = HashMap::new();
    m.insert('l', "less".to_string());
    m
}

impl PiprConfig {
    pub fn load_from_file(path: &Path) -> PiprConfig {
        if !path.exists() {
            let _ = std::fs::write(path, DEFAULT_CONFIG);
        }
        let content = std::fs::read_to_string(path).unwrap_or_default();
        let parsed: Result<crate::toml::Value, ConfigError> = crate::toml::parse(&content)
            .map_err(|e| ConfigError(format!("{} in {}", e, relative_to_cwd(path).display())));
        #[rustfmt::skip]
        let value = parsed
            .unwrap();
        PiprConfig::from_value(&value)
    }

    pub fn from_value(value: &crate::toml::Value) -> PiprConfig {
        let get = |k: &str| value.get(k);
        PiprConfig {
            finish_hook: get("finish_hook").and_then(|v| v.as_str()).map(|s| s.to_string()),
            paranoid_history_mode_default: get("paranoid_history_mode_default").and_then(|v| v.as_bool()).unwrap_or(false),
            autoeval_mode_default: get("autoeval_mode_default").and_then(|v| v.as_bool()).unwrap_or(false),
            history_size: get("history_size")
                .and_then(|v| v.as_integer())
                .map(|i| if i < 0 { 0 } else { i as usize })
                .unwrap_or(500),
            cmdlist_always_show_preview: get("cmdlist_always_show_preview").and_then(|v| v.as_bool()).unwrap_or(false),
            cmd_timeout_millis: get("cmd_timeout_millis")
                .and_then(|v| v.as_integer())
                .map(|i| if i < 0 { 0 } else { i as u64 })
                .unwrap_or(2000),
            highlighting_enabled: get("highlighting_enabled").and_then(|v| v.as_bool()).unwrap_or(true),
            eval_environment: get("eval_environment")
                .and_then(|v| v.as_array())
                .and_then(|a| a.iter().map(|x| x.as_str().map(|s| s.to_string())).collect::<Option<Vec<String>>>())
                .unwrap_or_else(|| vec!["bash".to_string(), "-c".to_string()]),
            snippets: char_map(get("snippets")).unwrap_or_default(),
            help_viewers: char_map(get("help_viewers")).unwrap_or_else(default_help_viewers),
            output_viewers: char_map(get("output_viewers")).unwrap_or_else(default_output_viewers),
        }
    }
}
