struct Parser<'a> {
    src: &'a str,
    bytes: &'a [u8],
    pos: usize,
    root: BTreeMap<String, Value>,
    /// path of the currently selected table
    current: Vec<String>,
    /// tables explicitly defined via [header]
    defined: Vec<Vec<String>>,
}

type PResult<T> = Result<T, (usize, usize, String)>;

pub fn parse(src: &str) -> Result<Value, Error> {
    let mut p = Parser {
        src,
        bytes: src.as_bytes(),
        pos: 0,
        root: BTreeMap::new(),
        current: Vec::new(),
        defined: Vec::new(),
    };
    match p.parse_document() {
        Ok(()) => Ok(Value::Table(p.root)),
        Err((pos, len, message)) => Err(Error { pos, len, message, input: src.to_string() }),
    }
}

fn is_bare_key_char(c: u8) -> bool {
    c.is_ascii_alphanumeric() || c == b'_' || c == b'-'
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<u8> {
        self.bytes.get(self.pos).copied()
    }

    fn peek_at(&self, off: usize) -> Option<u8> {
        self.bytes.get(self.pos + off).copied()
    }

    fn err<T>(&self, pos: usize, msg: &str) -> PResult<T> {
        Err((pos, 1, msg.to_string()))
    }

    fn skip_ws(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\t' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn skip_comment(&mut self) -> PResult<()> {
        if self.peek() == Some(b'#') {
            while let Some(c) = self.peek() {
                if c == b'\n' {
                    break;
                }
                if c == b'\r' && self.peek_at(1) == Some(b'\n') {
                    break;
                }
                if c < 0x20 && c != b'\t' {
                    return self.err(self.pos, "invalid comment");
                }
                self.pos += 1;
            }
        }
        Ok(())
    }

    fn skip_ws_comments_newlines(&mut self) -> PResult<()> {
        loop {
            self.skip_ws();
            self.skip_comment()?;
            match self.peek() {
                Some(b'\n') => self.pos += 1,
                Some(b'\r') if self.peek_at(1) == Some(b'\n') => self.pos += 2,
                _ => return Ok(()),
            }
        }
    }

    fn expect_newline_or_eof(&mut self) -> PResult<()> {
        self.skip_ws();
        self.skip_comment()?;
        match self.peek() {
            None => Ok(()),
            Some(b'\n') => {
                self.pos += 1;
                Ok(())
            }
            Some(b'\r') if self.peek_at(1) == Some(b'\n') => {
                self.pos += 2;
                Ok(())
            }
            Some(_) => Err((self.pos, 1, "expected newline, `#`".to_string())),
        }
    }

    fn parse_document(&mut self) -> PResult<()> {
        loop {
            self.skip_ws_comments_newlines()?;
            match self.peek() {
                None => return Ok(()),
                Some(b'[') => self.parse_table_header()?,
                Some(_) => self.parse_key_value()?,
            }
        }
    }

    fn parse_table_header(&mut self) -> PResult<()> {
        let start = self.pos;
        self.pos += 1; // [
        let array = if self.peek() == Some(b'[') {
            self.pos += 1;
            true
        } else {
            false
        };
        self.skip_ws();
        let key = self.parse_key()?;
        self.skip_ws();
        if self.peek() != Some(b']') {
            return self.err(self.pos, "invalid table header\nexpected `.`, `]`");
        }
        self.pos += 1;
        if array {
            if self.peek() != Some(b']') {
                return self.err(self.pos, "invalid table header\nexpected `]]`");
            }
            self.pos += 1;
        }
        self.expect_newline_or_eof()?;
        if array {
            // arrays of tables: append a new table
            let parent = &key[..key.len() - 1];
            let table = self.get_or_create_table(parent, start)?;
            let last = key.last().unwrap().clone();
            let entry = table.entry(last).or_insert_with(|| Value::Array(Vec::new()));
            match entry {
                Value::Array(a) => a.push(Value::Table(BTreeMap::new())),
                _ => return self.err(start, "duplicate key"),
            }
            self.current = key;
            self.defined.push(self.current.clone());
            return Ok(());
        }
        if self.defined.contains(&key) {
            return Err((start, key.join(".").len() + 2, format!("invalid table header\nduplicate key `{}` in document root", key.last().unwrap())));
        }
        self.get_or_create_table(&key, start)?;
        self.current = key.clone();
        self.defined.push(key);
        Ok(())
    }

    fn get_or_create_table(&mut self, path: &[String], errpos: usize) -> PResult<&mut BTreeMap<String, Value>> {
        let mut table: &mut BTreeMap<String, Value> = &mut self.root;
        for part in path {
            let entry = table.entry(part.clone()).or_insert_with(|| Value::Table(BTreeMap::new()));
            table = match entry {
                Value::Table(t) => t,
                Value::Array(a) => match a.last_mut() {
                    Some(Value::Table(t)) => t,
                    _ => return Err((errpos, 1, "duplicate key".to_string())),
                },
                _ => return Err((errpos, 1, format!("duplicate key `{}` in document root", part))),
            };
        }
        Ok(table)
    }

    fn parse_key(&mut self) -> PResult<Vec<String>> {
        let mut parts = Vec::new();
        loop {
            self.skip_ws();
            let part = self.parse_simple_key()?;
            parts.push(part);
            self.skip_ws();
            if self.peek() == Some(b'.') {
                self.pos += 1;
                continue;
            }
            break;
        }
        Ok(parts)
    }

    fn parse_simple_key(&mut self) -> PResult<String> {
        match self.peek() {
            Some(b'"') => self.parse_basic_string(),
            Some(b'\'') => self.parse_literal_string(),
            Some(c) if is_bare_key_char(c) => {
                let start = self.pos;
                while let Some(c) = self.peek() {
                    if is_bare_key_char(c) {
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                Ok(self.src[start..self.pos].to_string())
            }
            _ => self.err(self.pos, "invalid key"),
        }
    }

    fn parse_key_value(&mut self) -> PResult<()> {
        let key_start = self.pos;
        let key = self.parse_key()?;
        self.skip_ws();
        if self.peek() != Some(b'=') {
            return self.err(self.pos, "expected `.`, `=`");
        }
        self.pos += 1;
        self.skip_ws();
        let value = self.parse_value()?;
        self.expect_newline_or_eof()?;
        let current = self.current.clone();
        let mut full = current;
        full.extend(key[..key.len() - 1].iter().cloned());
        let table = self.get_or_create_table(&full, key_start)?;
        let last = key.last().unwrap().clone();
        if table.contains_key(&last) {
            return Err((key_start, last.len(), format!("duplicate key `{}`", last)));
        }
        table.insert(last, value);
        Ok(())
    }

    fn parse_value(&mut self) -> PResult<Value> {
        match self.peek() {
            None => self.err(self.pos, "invalid string\nexpected `\"`, `'`"),
            Some(b'"') => {
                if self.src[self.pos..].starts_with("\"\"\"") {
                    self.parse_ml_basic_string().map(Value::String)
                } else {
                    self.parse_basic_string().map(Value::String)
                }
            }
            Some(b'\'') => {
                if self.src[self.pos..].starts_with("'''") {
                    self.parse_ml_literal_string().map(Value::String)
                } else {
                    self.parse_literal_string().map(Value::String)
                }
            }
            Some(b'[') => self.parse_array(),
            Some(b'{') => self.parse_inline_table(),
            Some(b't') if self.src[self.pos..].starts_with("true") => {
                self.pos += 4;
                Ok(Value::Boolean(true))
            }
            Some(b'f') if self.src[self.pos..].starts_with("false") => {
                self.pos += 5;
                Ok(Value::Boolean(false))
            }
            Some(_) => self.parse_number_or_date(),
        }
    }

    fn parse_number_or_date(&mut self) -> PResult<Value> {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if c.is_ascii_alphanumeric() || matches!(c, b'+' | b'-' | b'_' | b'.' | b':') {
                self.pos += 1;
            } else if c == b' ' {
                // a date followed by a time
                if self.peek_at(1).map(|d| d.is_ascii_digit()).unwrap_or(false)
                    && self.src[start..self.pos].len() == 10
                    && self.src[start..self.pos].matches('-').count() == 2
                {
                    self.pos += 1;
                } else {
                    break;
                }
            } else {
                break;
            }
        }
        let text = &self.src[start..self.pos];
        if text.is_empty() {
            return self.err(start, "invalid string\nexpected `\"`, `'`");
        }
        let cleaned: String = text.chars().filter(|c| *c != '_').collect();
        if let Some(hex) = cleaned.strip_prefix("0x") {
            return i64::from_str_radix(hex, 16).map(Value::Integer).map_err(|_| (start, text.len(), "invalid hexadecimal integer".to_string()));
        }
        if let Some(oct) = cleaned.strip_prefix("0o") {
            return i64::from_str_radix(oct, 8).map(Value::Integer).map_err(|_| (start, text.len(), "invalid octal integer".to_string()));
        }
        if let Some(bin) = cleaned.strip_prefix("0b") {
            return i64::from_str_radix(bin, 2).map(Value::Integer).map_err(|_| (start, text.len(), "invalid binary integer".to_string()));
        }
        if let Ok(i) = cleaned.parse::<i64>() {
            if cleaned.len() > 1 && (cleaned.starts_with('0') || cleaned.starts_with("+0") || cleaned.starts_with("-0")) && cleaned.trim_start_matches(['+', '-']).len() > 1 {
                return Err((start, text.len(), "invalid integer\nleading zeros are not allowed".to_string()));
            }
            return Ok(Value::Integer(i));
        }
        if matches!(cleaned.as_str(), "inf" | "+inf" | "-inf" | "nan" | "+nan" | "-nan") {
            return Ok(Value::Float(cleaned.parse::<f64>().unwrap_or(f64::NAN)));
        }
        if cleaned.chars().any(|c| c == '.' || c == 'e' || c == 'E')
            && cleaned.chars().all(|c| c.is_ascii_digit() || matches!(c, '.' | 'e' | 'E' | '+' | '-'))
        {
            if let Ok(f) = cleaned.parse::<f64>() {
                return Ok(Value::Float(f));
            }
        }
        if text.chars().any(|c| c == ':' || c == '-') && text.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false) {
            return Ok(Value::Datetime(text.to_string()));
        }
        Err((start, text.len(), "invalid string\nexpected `\"`, `'`".to_string()))
    }

    fn parse_array(&mut self) -> PResult<Value> {
        self.pos += 1; // [
        let mut items = Vec::new();
        loop {
            self.skip_ws_comments_newlines()?;
            match self.peek() {
                None => return self.err(self.pos, "invalid array\nexpected `]`"),
                Some(b']') => {
                    self.pos += 1;
                    return Ok(Value::Array(items));
                }
                _ => {}
            }
            let v = self.parse_value()?;
            items.push(v);
            self.skip_ws_comments_newlines()?;
            match self.peek() {
                Some(b',') => {
                    self.pos += 1;
                }
                Some(b']') => {
                    self.pos += 1;
                    return Ok(Value::Array(items));
                }
                _ => return self.err(self.pos, "invalid array\nexpected `]`"),
            }
        }
    }

    fn parse_inline_table(&mut self) -> PResult<Value> {
        self.pos += 1; // {
        let mut table = BTreeMap::new();
        self.skip_ws();
        if self.peek() == Some(b'}') {
            self.pos += 1;
            return Ok(Value::Table(table));
        }
        loop {
            self.skip_ws();
            let key_start = self.pos;
            let key = self.parse_key()?;
            self.skip_ws();
            if self.peek() != Some(b'=') {
                return self.err(self.pos, "expected `.`, `=`");
            }
            self.pos += 1;
            self.skip_ws();
            let value = self.parse_value()?;
            // insert (dotted keys create sub tables)
            let mut t: &mut BTreeMap<String, Value> = &mut table;
            for part in &key[..key.len() - 1] {
                let entry = t.entry(part.clone()).or_insert_with(|| Value::Table(BTreeMap::new()));
                t = match entry {
                    Value::Table(t) => t,
                    _ => return Err((key_start, 1, "duplicate key".to_string())),
                };
            }
            let last = key.last().unwrap().clone();
            if t.contains_key(&last) {
                return Err((key_start, last.len(), format!("duplicate key `{}`", last)));
            }
            t.insert(last, value);
            self.skip_ws();
            match self.peek() {
                Some(b',') => {
                    self.pos += 1;
                }
                Some(b'}') => {
                    self.pos += 1;
                    return Ok(Value::Table(table));
                }
                _ => return self.err(self.pos, "invalid inline table\nexpected `}`"),
            }
        }
    }

    fn parse_escape(&mut self, out: &mut String) -> PResult<()> {
        // self.pos points at the char after the backslash
        let epos = self.pos;
        let c = match self.peek() {
            Some(c) => c,
            None => return self.err(epos, "invalid escape sequence\nexpected `b`, `f`, `n`, `r`, `t`, `u`, `U`, `\\`, `\"`"),
        };
        self.pos += 1;
        match c {
            b'b' => out.push('\u{8}'),
            b'f' => out.push('\u{c}'),
            b'n' => out.push('\n'),
            b'r' => out.push('\r'),
            b't' => out.push('\t'),
            b'\\' => out.push('\\'),
            b'"' => out.push('"'),
            b'u' | b'U' => {
                let n = if c == b'u' { 4 } else { 8 };
                let start = self.pos;
                for _ in 0..n {
                    match self.peek() {
                        Some(h) if h.is_ascii_hexdigit() => self.pos += 1,
                        _ => return Err((self.pos, 1, "invalid unicode escape".to_string())),
                    }
                }
                let code = u32::from_str_radix(&self.src[start..self.pos], 16).unwrap_or(0);
                match char::from_u32(code) {
                    Some(ch) => out.push(ch),
                    None => return Err((start, n, "invalid unicode scalar value".to_string())),
                }
            }
            _ => {
                return Err((epos, 1, "invalid escape sequence\nexpected `b`, `f`, `n`, `r`, `t`, `u`, `U`, `\\`, `\"`".to_string()));
            }
        }
        Ok(())
    }

    fn parse_basic_string(&mut self) -> PResult<String> {
        let start = self.pos;
        self.pos += 1; // "
        let mut out = String::new();
        loop {
            match self.peek() {
                None | Some(b'\n') => {
                    return Err((start, self.pos - start, "invalid basic string".to_string()));
                }
                Some(b'"') => {
                    self.pos += 1;
                    return Ok(out);
                }
                Some(b'\\') => {
                    self.pos += 1;
                    self.parse_escape(&mut out)?;
                }
                Some(c) if c < 0x20 && c != b'\t' => {
                    return self.err(self.pos, "invalid basic string");
                }
                Some(_) => {
                    let ch = self.src[self.pos..].chars().next().unwrap();
                    out.push(ch);
                    self.pos += ch.len_utf8();
                }
            }
        }
    }

    fn parse_ml_basic_string(&mut self) -> PResult<String> {
        let start = self.pos;
        self.pos += 3;
        // a newline immediately following the opening delimiter is trimmed
        if self.peek() == Some(b'\n') {
            self.pos += 1;
        } else if self.peek() == Some(b'\r') && self.peek_at(1) == Some(b'\n') {
            self.pos += 2;
        }
        let mut out = String::new();
        loop {
            if self.src[self.pos..].starts_with("\"\"\"") {
                self.pos += 3;
                // up to two additional quotes belong to the content
                while self.peek() == Some(b'"') && out.len() < usize::MAX {
                    out.push('"');
                    self.pos += 1;
                }
                return Ok(out);
            }
            match self.peek() {
                None => return Err((start, 3, "invalid multiline basic string".to_string())),
                Some(b'\\') => {
                    self.pos += 1;
                    // line ending backslash
                    let save = self.pos;
                    self.skip_ws();
                    if matches!(self.peek(), Some(b'\n') | Some(b'\r')) {
                        self.skip_ws_comments_newlines_no_comment();
                        continue;
                    }
                    self.pos = save;
                    self.parse_escape(&mut out)?;
                }
                Some(_) => {
                    let ch = self.src[self.pos..].chars().next().unwrap();
                    out.push(ch);
                    self.pos += ch.len_utf8();
                }
            }
        }
    }

    fn skip_ws_comments_newlines_no_comment(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn parse_literal_string(&mut self) -> PResult<String> {
        let start = self.pos;
        self.pos += 1; // '
        let s = self.pos;
        loop {
            match self.peek() {
                None | Some(b'\n') => return Err((start, self.pos - start, "invalid literal string".to_string())),
                Some(b'\'') => {
                    let out = self.src[s..self.pos].to_string();
                    self.pos += 1;
                    return Ok(out);
                }
                Some(c) if c < 0x20 && c != b'\t' => return self.err(self.pos, "invalid literal string"),
                Some(_) => {
                    let ch = self.src[self.pos..].chars().next().unwrap();
                    self.pos += ch.len_utf8();
                }
            }
        }
    }

    fn parse_ml_literal_string(&mut self) -> PResult<String> {
        let start = self.pos;
        self.pos += 3;
        if self.peek() == Some(b'\n') {
            self.pos += 1;
        } else if self.peek() == Some(b'\r') && self.peek_at(1) == Some(b'\n') {
            self.pos += 2;
        }
        let s = self.pos;
        loop {
            if self.src[self.pos..].starts_with("'''") {
                let mut end = self.pos;
                self.pos += 3;
                while self.peek() == Some(b'\'') {
                    end += 1;
                    self.pos += 1;
                }
                return Ok(self.src[s..end].to_string());
            }
            match self.peek() {
                None => return Err((start, 3, "invalid multiline literal string".to_string())),
                Some(_) => {
                    let ch = self.src[self.pos..].chars().next().unwrap();
                    self.pos += ch.len_utf8();
                }
            }
        }
    }
}
EOF
