//! Asynchronous command execution.

use std::io::{Read, Write};
use std::process::{Child, Command, Stdio};
use std::sync::mpsc::{channel, Receiver, RecvTimeoutError, Sender};
use std::thread;
use std::time::{Duration, Instant};

pub struct ExecRequest {
    pub command: String,
    pub stdin: Option<String>,
}

#[derive(Debug, Clone)]
pub enum ExecResult {
    Finished { success: bool, stdout: String, stderr: String },
    TimedOut,
}

struct Running {
    child: Child,
    started: Instant,
    stdout_rx: Receiver<String>,
    stderr_rx: Receiver<String>,
}

fn read_to_string_lossy<R: Read + Send + 'static>(mut r: R) -> Receiver<String> {
    let (tx, rx) = channel();
    thread::spawn(move || {
        let mut s = String::new();
        let res = match r.read_to_string(&mut s) {
            Ok(_) => s,
            Err(e) => e.to_string(),
        };
        let _ = tx.send(res);
    });
    rx
}

/// Builds the command used to evaluate a shell snippet.
pub fn build_command(eval_env: &[String], isolation: bool, command: &str) -> Command {
    let mut parts: Vec<String> = Vec::new();
    if isolation {
        parts.extend(
            [
                "bwrap", "--ro-bind", "/", "/", "--tmpfs", "/tmp", "--dev", "/dev", "--proc", "/proc",
                "--die-with-parent", "--share-net", "--unshare-pid",
            ]
            .iter()
            .map(|s| s.to_string()),
        );
    }
    parts.extend(eval_env.iter().cloned());
    parts.push(command.to_string());
    let (prog, args) = if parts.is_empty() { ("bash".to_string(), Vec::new()) } else { (parts[0].clone(), parts[1..].to_vec()) };
    let mut cmd = Command::new(prog);
    cmd.args(args);
    cmd
}

pub struct Executor {
    tx: Sender<ExecRequest>,
    pub rx: Receiver<ExecResult>,
}

impl Executor {
    pub fn start(eval_env: Vec<String>, isolation: bool, timeout: Duration) -> Executor {
        let (req_tx, req_rx) = channel::<ExecRequest>();
        let (res_tx, res_rx) = channel::<ExecResult>();
        thread::spawn(move || run_loop(req_rx, res_tx, eval_env, isolation, timeout));
        Executor { tx: req_tx, rx: res_rx }
    }

    pub fn execute(&self, command: String, stdin: Option<String>) {
        let _ = self.tx.send(ExecRequest { command, stdin });
    }
}

fn spawn(eval_env: &[String], isolation: bool, req: &ExecRequest) -> Option<Running> {
    let mut cmd = build_command(eval_env, isolation, &req.command);
    cmd.stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped());
    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(_) => return None,
    };
    if let Some(mut stdin) = child.stdin.take() {
        if let Some(data) = &req.stdin {
            let _ = stdin.write_all(data.as_bytes());
        }
        drop(stdin);
    }
    let stdout_rx = read_to_string_lossy(child.stdout.take().unwrap());
    let stderr_rx = read_to_string_lossy(child.stderr.take().unwrap());
    Some(Running { child, started: Instant::now(), stdout_rx, stderr_rx })
}

fn run_loop(req_rx: Receiver<ExecRequest>, res_tx: Sender<ExecResult>, eval_env: Vec<String>, isolation: bool, timeout: Duration) {
    let mut running: Option<Running> = None;
    loop {
        let req = if running.is_some() {
            match req_rx.recv_timeout(Duration::from_millis(5)) {
                Ok(r) => Some(r),
                Err(RecvTimeoutError::Timeout) => None,
                Err(RecvTimeoutError::Disconnected) => return,
            }
        } else {
            match req_rx.recv() {
                Ok(r) => Some(r),
                Err(_) => return,
            }
        };
        if let Some(mut req) = req {
            // only the most recent request matters
            while let Ok(newer) = req_rx.try_recv() {
                req = newer;
            }
            if let Some(mut r) = running.take() {
                let _ = r.child.kill();
                let _ = r.child.wait();
            }
            match spawn(&eval_env, isolation, &req) {
                Some(r) => running = Some(r),
                None => {
                    let _ = res_tx.send(ExecResult::Finished {
                        success: false,
                        stdout: String::new(),
                        stderr: String::new(),
                    });
                }
            }
        }
        if let Some(r) = &mut running {
            match r.child.try_wait() {
                Ok(Some(status)) => {
                    let stdout = r.stdout_rx.recv().unwrap_or_default();
                    let stderr = r.stderr_rx.recv().unwrap_or_default();
                    let _ = res_tx.send(ExecResult::Finished { success: status.success(), stdout, stderr });
                    running = None;
                }
                Ok(None) => {
                    if r.started.elapsed() >= timeout {
                        let _ = res_tx.send(ExecResult::TimedOut);
                        // the process is left running
                        running = None;
                    }
                }
                Err(_) => {
                    let _ = res_tx.send(ExecResult::Finished {
                        success: false,
                        stdout: String::new(),
                        stderr: String::new(),
                    });
                    running = None;
                }
            }
        }
    }
}

/// Runs a command synchronously, returning (success, stdout). The stdin pipe is
/// left open while the command runs.
pub fn run_blocking(eval_env: &[String], isolation: bool, command: &str) -> Option<(bool, String)> {
    let mut cmd = build_command(eval_env, isolation, command);
    cmd.stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped());
    let mut child = cmd.spawn().ok()?;
    let stdout_rx = read_to_string_lossy(child.stdout.take()?);
    let stderr_rx = read_to_string_lossy(child.stderr.take()?);
    let stdout = stdout_rx.recv().unwrap_or_default();
    let _ = stderr_rx.recv();
    let status = child.wait().ok()?;
    Some((status.success(), stdout))
}
