//! Application state and key handling.

use std::collections::HashMap;
use std::path::PathBuf;
use std::time::Duration;

use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};

use crate::cmdlist::CommandList;
use crate::executor::{ExecResult, Executor};
use crate::input::Input;
use crate::pipr_config::PiprConfig;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Window {
    Main,
    Help(Box<Window>),
    History(Box<Window>, usize),
    Bookmarks(Box<Window>, usize),
    Snippets,
    HelpViewer(String),
    OutputViewer,
}

#[derive(Clone, Debug)]
pub struct Cache {
    pub prefix: String,
    pub output: Option<String>,
}

#[derive(Clone, Debug)]
pub struct Suggestions {
    pub items: Vec<String>,
    pub selected: usize,
    pub range: std::ops::Range<usize>,
}

/// Something the UI loop has to do outside of the drawing loop.
pub enum Action {
    None,
    Exit,
    RunHelpViewer(String),
    RunOutputViewer(String),
}

pub struct App {
    pub input: Input,
    pub config: PiprConfig,
    pub autoeval: bool,
    pub paranoid: bool,
    pub history: CommandList,
    pub bookmarks: CommandList,
    pub history_idx: Option<usize>,
    pub last_executed: Option<String>,
    pub output: String,
    pub stderr: Option<String>,
    pub running: bool,
    pub cache: Option<Cache>,
    pub window: Window,
    pub suggestions: Option<Suggestions>,
    pub executor: Executor,
    pub isolation: bool,
    pub should_exit: bool,
}

impl App {
    pub fn new(config: PiprConfig, config_dir: PathBuf, isolation: bool) -> App {
        let history = CommandList::load(config_dir.join("history"), Some(config.history_size));
        let bookmarks = CommandList::load(config_dir.join("bookmarks"), None);
        let executor = Executor::start(
            config.eval_environment.clone(),
            isolation,
            Duration::from_millis(config.cmd_timeout_millis),
        );
        App {
            input: Input::new(),
            autoeval: config.autoeval_mode_default,
            paranoid: config.paranoid_history_mode_default,
            config,
            history,
            bookmarks,
            history_idx: None,
            last_executed: None,
            output: String::new(),
            stderr: None,
            running: false,
            cache: None,
            window: Window::Main,
            suggestions: None,
            executor,
            isolation,
            should_exit: false,
        }
    }

    // ------------------------------------------------------------------
    // command helpers

    /// The lines of the command, excluding comment lines, joined by spaces.
    pub fn executable_command(&self) -> String {
        self.input
            .lines
            .iter()
            .filter(|l| !l.starts_with('#'))
            .cloned()
            .collect::<Vec<String>>()
            .join(" ")
    }

    /// All lines joined by a single space.
    pub fn joined_command(&self) -> String {
        self.input.lines.join(" ")
    }

    pub fn is_bookmarked(&self) -> bool {
        self.bookmarks.contains(&self.input.lines)
    }

    pub fn output_stale(&self) -> bool {
        match &self.last_executed {
            Some(c) => *c != self.input.content(),
            None => true,
        }
    }

    pub fn execute(&mut self) {
        self.last_executed = Some(self.input.content());
        self.running = true;
        self.update_cache_validity();
        let command = self.executable_command();
        if let Some(cache) = &self.cache {
            if let Some(out) = &cache.output {
                let joined = self.joined_command();
                let suffix_start = (cache.prefix.len() + 1).min(joined.len());
                let suffix = joined[suffix_start..].to_string();
                self.executor.execute(suffix, Some(out.clone()));
                return;
            }
        }
        self.executor.execute(command, None);
    }

    fn update_cache_validity(&mut self) {
        if let Some(cache) = &self.cache {
            if !self.joined_command().starts_with(&cache.prefix) {
                self.cache = None;
            }
        }
    }

    pub fn on_text_changed(&mut self) {
        self.history_idx = None;
        self.update_cache_validity();
        if self.autoeval {
            self.execute();
        }
    }

    pub fn handle_exec_result(&mut self, res: ExecResult) {
        self.running = false;
        match res {
            ExecResult::Finished { success, stdout, stderr } => {
                if success {
                    self.output = stdout;
                    self.stderr = None;
                    if self.autoeval && self.paranoid {
                        self.history.push(self.input.lines.clone());
                    }
                } else {
                    self.stderr = Some(stderr);
                }
            }
            ExecResult::TimedOut => {
                self.stderr = Some("Command timed out".to_string());
            }
        }
    }

    pub fn push_history(&mut self) {
        self.history.push(self.input.lines.clone());
    }

    // ------------------------------------------------------------------
    // history navigation

    fn history_prev(&mut self) {
        match self.history_idx {
            None => {
                let idx = self.history.len().saturating_sub(1);
                let was_empty = self.history.is_empty();
                self.push_history();
                if was_empty {
                    return;
                }
                self.history_idx = Some(idx);
                if let Some(e) = self.history.get(idx) {
                    let e = e.clone();
                    self.input.set_lines(e);
                }
            }
            Some(i) => {
                if i > 0 {
                    self.history_idx = Some(i - 1);
                    if let Some(e) = self.history.get(i - 1) {
                        let e = e.clone();
                        self.input.set_lines(e);
                    }
                }
            }
        }
    }

    fn history_next(&mut self) {
        if let Some(i) = self.history_idx {
            if i + 2 >= self.history.len() {
                self.history_idx = None;
                self.input.clear();
            } else {
                self.history_idx = Some(i + 1);
                if let Some(e) = self.history.get(i + 1) {
                    let e = e.clone();
                    self.input.set_lines(e);
                }
            }
        }
    }

    // ------------------------------------------------------------------
    // caching

    fn toggle_cache_at_cursor(&mut self) {
        let joined = self.joined_command();
        let idx = self.input.joined_cursor_idx();
        if joined[idx..].chars().next() != Some('|') {
            return;
        }
        let prefix = joined[..idx].to_string();
        let result = crate::executor::run_blocking(&self.config.eval_environment, self.isolation, &prefix);
        match result {
            Some((true, out)) => {
                self.cache = Some(Cache { prefix, output: Some(out) });
            }
            _ => {
                self.cache = None;
            }
        }
    }

    // ------------------------------------------------------------------
    // suggestions

    fn complete(&mut self) {
        let (range, word) = self.input.word_under_cursor();
        let items = file_suggestions(&word);
        if items.is_empty() {
            return;
        }
        if items.len() == 1 {
            self.input.replace_range(range, &items[0]);
            return;
        }
        self.suggestions = Some(Suggestions { items, selected: 0, range });
    }

    fn apply_suggestion(&mut self) {
        if let Some(s) = self.suggestions.take() {
            if let Some(item) = s.items.get(s.selected) {
                let item = item.clone();
                self.input.replace_range(s.range.clone(), &item);
            }
        }
    }

    // ------------------------------------------------------------------
    // key handling

    pub fn handle_key(&mut self, key: KeyEvent) -> Action {
        let window = self.window.clone();
        match window {
            Window::Main => self.handle_main_key(key),
            Window::Help(prev) => {
                match key.code {
                    KeyCode::F(4) => self.window = Window::History(prev, self.history.len().saturating_sub(1)),
                    KeyCode::Char('b') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        self.window = Window::Bookmarks(prev, self.bookmarks.len().saturating_sub(1))
                    }
                    _ => self.window = *prev,
                }
                Action::None
            }
            Window::History(prev, sel) => {
                self.handle_list_key(key, prev, sel, true);
                Action::None
            }
            Window::Bookmarks(prev, sel) => {
                self.handle_list_key(key, prev, sel, false);
                Action::None
            }
            Window::Snippets => {
                self.window = Window::Main;
                if let Some(a) = self.handle_global_key(&key, Window::Snippets) {
                    return a;
                }
                if let KeyCode::Char(c) = key.code {
                    if let Some(snippet) = self.config.snippets.get(&c).cloned() {
                        self.insert_snippet(&snippet);
                    }
                }
                Action::None
            }
            Window::HelpViewer(word) => {
                self.window = Window::Main;
                if let Some(a) = self.handle_global_key(&key, Window::HelpViewer(word.clone())) {
                    return a;
                }
                if let KeyCode::Char(c) = key.code {
                    if let Some(viewer) = self.config.help_viewers.get(&c).cloned() {
                        return Action::RunHelpViewer(viewer.replace("??", &word));
                    }
                }
                Action::None
            }
            Window::OutputViewer => {
                self.window = Window::Main;
                if let Some(a) = self.handle_global_key(&key, Window::OutputViewer) {
                    return a;
                }
                if let KeyCode::Char(c) = key.code {
                    if let Some(viewer) = self.config.output_viewers.get(&c).cloned() {
                        return Action::RunOutputViewer(viewer);
                    }
                }
                Action::None
            }
        }
    }

    /// Keys that open the help / list windows from any non-list window.
    fn handle_global_key(&mut self, key: &KeyEvent, current: Window) -> Option<Action> {
        match key.code {
            KeyCode::F(1) => {
                self.window = Window::Help(Box::new(current));
                Some(Action::None)
            }
            KeyCode::F(4) => {
                self.push_history();
                self.window = Window::History(Box::new(current), self.history.len().saturating_sub(1));
                Some(Action::None)
            }
            KeyCode::Char('b') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.push_history();
                self.window = Window::Bookmarks(Box::new(current), self.bookmarks.len().saturating_sub(1));
                Some(Action::None)
            }
            _ => None,
        }
    }

    fn insert_snippet(&mut self, snippet: &str) {
        let cursor_pos = snippet.find("||");
        let text = snippet.replace("||", "");
        match cursor_pos {
            Some(pos) => {
                let before = &text[..pos];
                let after = &text[pos..];
                self.input.insert_str(before);
                let (line, col) = (self.input.line, self.input.col);
                self.input.insert_str(after);
                self.input.line = line;
                self.input.col = col;
            }
            None => self.input.insert_str(&text),
        }
        self.history_idx = None;
        self.update_cache_validity();
    }

    fn handle_list_key(&mut self, key: KeyEvent, prev: Box<Window>, sel: usize, is_history: bool) {
        let len = if is_history { self.history.len() } else { self.bookmarks.len() };
        let set_window = |app: &mut App, prev: Box<Window>, sel: usize| {
            app.window = if is_history { Window::History(prev, sel) } else { Window::Bookmarks(prev, sel) };
        };
        match key.code {
            KeyCode::Esc => {
                self.close_list(is_history);
                self.window = *prev;
            }
            KeyCode::F(4) => {
                self.close_list(is_history);
                if is_history {
                    self.window = *prev;
                } else {
                    self.window = Window::History(prev, self.history.len().saturating_sub(1));
                }
            }
            KeyCode::Char('b') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.close_list(is_history);
                if is_history {
                    self.window = Window::Bookmarks(prev, self.bookmarks.len().saturating_sub(1));
                } else {
                    self.window = *prev;
                }
            }
            KeyCode::F(1) => {
                self.close_list(is_history);
                self.window = Window::Help(prev);
            }
            KeyCode::Up | KeyCode::Char('k') => {
                let s = if sel > 0 { sel - 1 } else { 0 };
                set_window(self, prev, s);
            }
            KeyCode::Down | KeyCode::Char('j') => {
                let s = if len > 0 && sel + 1 < len { sel + 1 } else { sel };
                set_window(self, prev, s);
            }
            KeyCode::Delete => {
                if is_history {
                    self.history.remove(sel);
                } else {
                    self.bookmarks.remove(sel);
                }
                let new_len = if is_history { self.history.len() } else { self.bookmarks.len() };
                let s = if new_len == 0 { 0 } else { sel.min(new_len - 1) };
                set_window(self, prev, s);
            }
            KeyCode::Enter => {
                let entry = if is_history { self.history.get(sel).cloned() } else { self.bookmarks.get(sel).cloned() };
                if let Some(e) = entry {
                    self.input.set_lines(e);
                    self.history_idx = None;
                    self.update_cache_validity();
                }
                self.close_list(is_history);
                self.window = *prev;
            }
            _ => {
                set_window(self, prev, sel);
            }
        }
    }

    fn close_list(&mut self, is_history: bool) {
        if is_history {
            self.history.save();
        } else {
            self.bookmarks.save();
        }
    }

    fn handle_main_key(&mut self, key: KeyEvent) -> Action {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        let alt = key.modifiers.contains(KeyModifiers::ALT);

        if self.suggestions.is_some() {
            match key.code {
                KeyCode::Tab => {
                    if let Some(s) = &mut self.suggestions {
                        s.selected = (s.selected + 1) % s.items.len();
                    }
                    return Action::None;
                }
                KeyCode::BackTab | KeyCode::Up => {
                    if let Some(s) = &mut self.suggestions {
                        s.selected = if s.selected == 0 { s.items.len() - 1 } else { s.selected - 1 };
                    }
                    return Action::None;
                }
                KeyCode::Down => {
                    if let Some(s) = &mut self.suggestions {
                        s.selected = (s.selected + 1) % s.items.len();
                    }
                    return Action::None;
                }
                KeyCode::Enter => {
                    self.apply_suggestion();
                    self.history_idx = None;
                    self.update_cache_validity();
                    return Action::None;
                }
                KeyCode::F(1) | KeyCode::F(4) => {
                    self.suggestions = None;
                }
                KeyCode::Char('b') if ctrl => {
                    self.suggestions = None;
                }
                _ => {
                    self.suggestions = None;
                    return Action::None;
                }
            }
        }

        if let Some(a) = self.handle_global_key(&key, Window::Main) {
            return a;
        }

        match key.code {
            KeyCode::Esc => {
                return Action::Exit;
            }
            KeyCode::Char('c') if ctrl => {
                return Action::Exit;
            }
            KeyCode::F(2) => {
                self.autoeval = !self.autoeval;
            }
            KeyCode::F(3) => {
                self.paranoid = !self.paranoid;
            }
            KeyCode::F(5) => {
                let (_, word) = self.input.word_under_cursor();
                if !word.is_empty() {
                    self.window = Window::HelpViewer(word);
                }
            }
            KeyCode::F(6) => {
                self.window = Window::OutputViewer;
            }
            KeyCode::F(7) => {
                self.toggle_cache_at_cursor();
            }
            KeyCode::Char('s') if ctrl => {
                self.bookmarks.toggle(self.input.lines.clone());
            }
            KeyCode::Char('v') if ctrl => {
                self.window = Window::Snippets;
            }
            KeyCode::Char('p') if ctrl => {
                self.history_prev();
                self.update_cache_validity();
            }
            KeyCode::Char('n') if ctrl => {
                self.history_next();
                self.update_cache_validity();
            }
            KeyCode::Char('x') if ctrl => {
                self.push_history();
                self.input.clear();
                self.history_idx = None;
                self.update_cache_validity();
            }
            KeyCode::Tab => {
                self.complete();
                self.history_idx = None;
                self.update_cache_validity();
            }
            KeyCode::Enter if alt => {
                self.input.newline();
                self.on_text_changed();
            }
            KeyCode::Enter => {
                self.push_history();
                self.execute();
            }
            KeyCode::Char('u') if ctrl => {
                self.input.clear();
                self.on_text_changed();
            }
            KeyCode::Char('w') if ctrl => {
                self.input.delete_word();
                self.on_text_changed();
            }
            KeyCode::Char('a') if ctrl => self.input.home(),
            KeyCode::Char('e') if ctrl => self.input.end(),
            KeyCode::Backspace => {
                self.input.backspace();
                self.on_text_changed();
            }
            KeyCode::Delete => {
                self.input.delete();
                self.on_text_changed();
            }
            KeyCode::Left => self.input.left(),
            KeyCode::Right => self.input.right(),
            KeyCode::Up => self.input.up(),
            KeyCode::Down => self.input.down(),
            KeyCode::Home => self.input.home(),
            KeyCode::End => self.input.end(),
            KeyCode::Char(c) => {
                self.input.insert_char(c);
                self.on_text_changed();
            }
            _ => {}
        }
        Action::None
    }

    pub fn snippet_entries(&self) -> Vec<String> {
        self.config.snippets.iter().map(|(k, v)| format!("{}: {}", k, v.replace("||", ""))).collect()
    }

    pub fn viewer_entries(map: &HashMap<char, String>, word: Option<&str>) -> Vec<String> {
        map.iter()
            .map(|(k, v)| {
                let v = match word {
                    Some(w) => v.replace("??", w),
                    None => v.clone(),
                };
                format!("{}: {}", k, v)
            })
            .collect()
    }
}

fn expand_tilde(path: &str) -> String {
    if path == "~" || path.starts_with("~/") {
        if let Some(home) = dirs::home_dir() {
            return format!("{}{}", home.display(), &path[1..]);
        }
    }
    path.to_string()
}

/// File name completions for `word`.
pub fn file_suggestions(word: &str) -> Vec<String> {
    let (dir_display, dir_fs, prefix): (String, String, String) = if word.is_empty() {
        ("./".to_string(), ".".to_string(), String::new())
    } else if std::path::Path::new(&expand_tilde(word)).is_dir() {
        let display = if word.ends_with('/') { word.to_string() } else { format!("{}/", word) };
        (display, expand_tilde(word), String::new())
    } else if let Some(i) = word.rfind('/') {
        let dir = &word[..=i];
        (dir.to_string(), expand_tilde(dir), word[i + 1..].to_string())
    } else {
        return Vec::new();
    };
    let entries = match std::fs::read_dir(&dir_fs) {
        Ok(e) => e,
        Err(_) => return Vec::new(),
    };
    let mut result = Vec::new();
    for entry in entries.flatten() {
        let name = entry.file_name().to_string_lossy().to_string();
        if name.starts_with(&prefix) {
            result.push(format!("{}{}", dir_display, name));
        }
    }
    result
}
