use crate::ansi;
use crate::app::{App, Window};
use crate::highlight;
use crate::tui::{draw_block, draw_lines, draw_right_aligned, Buffer, Color, Modifier, Rect, Span, Style};

pub const SPINNER: [&str; 6] = ["⠾", "⠽", "⠻", "⠟", "⠯", "⠷"];

pub const HELP_TEXT: &[&str] = &[
    "F1         Show/hide help",
