    "this will simply exclude the line from the executed command.",
    "",
    "Config file is in",
    "~/.config/pipr/pipr.toml",
];

fn focused_title_style() -> Style {
    Style::new().fg(Color::Black).bg(Color::Cyan)
}

fn title_style() -> Style {
    Style::new().fg(Color::Cyan)
}

/// Splits `area` vertically: the first part gets `first` rows (clamped).
fn split_v(area: Rect, first: u16) -> (Rect, Rect) {
    let h = first.min(area.height);
    (
        Rect::new(area.x, area.y, area.width, h),
        Rect::new(area.x, area.y + h, area.width, area.height - h),
    )
}

/// Splits `area` into two halves (percentages rounded, first gets the extra row).
fn split_half_v(area: Rect) -> (Rect, Rect) {
    let first = ((area.height as f64) * 0.5).round() as u16;
    split_v(area, first)
}

fn split_h_percent(area: Rect, percent: f64) -> (Rect, Rect) {
    let w = ((area.width as f64) * percent).round() as u16;
    let w = w.min(area.width);
    (
        Rect::new(area.x, area.y, w, area.height),
        Rect::new(area.x + w, area.y, area.width - w, area.height),
    )
}

pub fn draw(app: &App, buf: &mut Buffer, spinner_frame: usize) -> Option<(u16, u16)> {
    let full = buf.area;
    let area = full.inner(1);
    let mut cursor = None;

    match &app.window {
        Window::Help(_) => {
            let inner = draw_block(buf, area, " Help ", focused_title_style());
            let lines: Vec<Vec<Span>> = HELP_TEXT.iter().map(|l| vec![Span::raw(*l)]).collect();
            draw_lines(buf, inner, &lines);
        }
        Window::History(_, sel) => {
            draw_list(app, buf, area, " History ", &app.history.entries, *sel);
        }
        Window::Bookmarks(_, sel) => {
            draw_list(app, buf, area, " Bookmarks ", &app.bookmarks.entries, *sel);
        }
        _ => {
            let main_area = match &app.window {
                Window::Snippets | Window::HelpViewer(_) | Window::OutputViewer => {
                    let (left, right) = split_h_percent(area, 0.4);
                    let entries = match &app.window {
                        Window::Snippets => app.snippet_entries(),
                        Window::HelpViewer(word) => App::viewer_entries(&app.config.help_viewers, Some(word)),
                        _ => App::viewer_entries(&app.config.output_viewers, None),
                    };
                    let inner = draw_block(buf, left, " Open in ", title_style());
                    let lines: Vec<Vec<Span>> = entries.iter().map(|e| vec![Span::raw(e.clone())]).collect();
                    draw_lines(buf, inner, &lines);
                    right
                }
                _ => area,
            };
            cursor = draw_main(app, buf, main_area, spinner_frame);
        }
    }

    // help hint at the bottom right
    if area.height > 0 && area.width >= 10 {
        let hint_area = Rect::new(area.x, area.bottom() - 1, area.width - 3, 1);
        draw_right_aligned(buf, hint_area, "Help: F1", Style::default());
    } else if area.height > 0 {
        let hint_area = Rect::new(area.x, area.bottom() - 1, area.width, 1);
        draw_right_aligned(buf, hint_area, "Help: F1", Style::default());
    }
    cursor
}

fn draw_list(app: &App, buf: &mut Buffer, area: Rect, title: &str, entries: &[Vec<String>], sel: usize) {
    let show_preview = app.config.cmdlist_always_show_preview
        || entries.get(sel).map(|e| e.len() > 1).unwrap_or(false);
    let (list_area, preview_area) = split_half_v(area);
    let inner = draw_block(buf, list_area, title, focused_title_style());
    if inner.height > 0 {
        let visible = inner.height as usize;
        let offset = if entries.is_empty() { 0 } else { sel.saturating_sub(visible - 1) };
        for (row, entry) in entries.iter().skip(offset).take(visible).enumerate() {
            let idx = offset + row;
            let text = entry.join(" ↵ ");
            let y = inner.y + row as u16;
            if idx == sel {
                let style = Style::new().modifier(Modifier::ITALIC);
                buf.set_style(Rect::new(inner.x, y, inner.width, 1), style);
                buf.set_stringn(inner.x, y, &format!(">>{}", text), inner.width as usize, style);
            } else {
                buf.set_stringn(inner.x, y, &format!("  {}", text), inner.width as usize, Style::default());
            }
        }
    }
    if show_preview {
        let pinner = draw_block(buf, preview_area, " Preview ", title_style());
        if let Some(entry) = entries.get(sel) {
            let lines: Vec<Vec<Span>> = entry.iter().map(|l| vec![Span::raw(l.clone())]).collect();
            draw_lines(buf, pinner, &lines);
        }
    }
}

fn command_title(app: &App) -> String {
    let mut t = String::from(" Command");
    if app.is_bookmarked() {
        t.push_str(" [Bookmarked]");
    }
    if app.autoeval {
        t.push_str(" [Autoeval]");
    }
    if app.cache.is_some() {
        t.push_str(" [Caching]");
    }
    if app.autoeval && app.paranoid {
        t.push_str(" [Paranoid]");
    }
    t.push(' ');
    t
}

fn output_title(app: &App, spinner_frame: usize) -> String {
    let mut t = String::from(" Output");
    if app.output_stale() {
        t.push_str(" [+]");
    }
    if app.running {
        t.push(' ');
        t.push_str(SPINNER[spinner_frame % SPINNER.len()]);
    }
    t.push(' ');
    t
}

/// Prepares the displayed command lines (truncated) for the given inner width.
fn display_command_lines(app: &App, inner_width: usize) -> Vec<String> {
    let mut lines = Vec::new();
    for line in &app.input.lines {
        let mut l = line.clone();
        let max_len = inner_width.saturating_sub(3);
        if l.len() > max_len {
            l
            .truncate(max_len);
            l.push_str("...");
        }
        lines.push(l);
    }
    lines
}

fn draw_main(app: &App, buf: &mut Buffer, area: Rect, spinner_frame: usize) -> Option<(u16, u16)> {
    let n_lines = app.input.lines.len() as u16;
    let (cmd_area, rest) = split_v(area, n_lines.saturating_add(2));

    // --- command box
    let cmd_inner = draw_block(buf, cmd_area, &command_title(app), focused_title_style());
    let display = display_command_lines(app, cmd_inner.width as usize);
    let text = display.join("\n");
    let lines = if app.config.highlighting_enabled { highlight::highlight(&text) } else { highlight::plain(&text) };
    draw_lines(buf, cmd_inner, &lines);
    let cur_line = app.input.current_line();
    let before: String = cur_line.chars().take(app.input.col).collect();
    let cursor_x = cmd_area.x.saturating_add(1).saturating_add(before.width() as u16);
    let cursor_y = cmd_area.y.saturating_add(1).saturating_add(app.input.line as u16);
    let cursor = Some((cursor_x, cursor_y));

    // --- suggestions
    let mut rest = rest;
    if let Some(s) = &app.suggestions {
        let (sugg_area, r) = split_v(rest, 7);
        rest = r;
        let inner = draw_block(buf, sugg_area, " Suggestions ", title_style());
        if inner.height > 0 {
            let visible = inner.height as usize;
            let offset = s.selected.saturating_sub(visible - 1);
            for (row, item) in s.items.iter().skip(offset).take(visible).enumerate() {
                let idx = offset + row;
                let y = inner.y + row as u16;
                if idx == s.selected {
                    let style = Style::new().fg(Color::Black).bg(Color::White);
                    buf.set_style(Rect::new(inner.x, y, inner.width, 1), style);
                    buf.set_stringn(inner.x, y, item, inner.width as usize, style);
                } else {
                    buf.set_stringn(inner.x, y, item, inner.width as usize, Style::default());
                }
            }
        }
    }

    // --- output (and stderr)
    let (out_area, err_area) = match &app.stderr {
        Some(_) => {
            let (a, b) = split_half_v(rest);
            (a, Some(b))
        }
        None => (rest, None),
    };
    let out_inner = draw_block(buf, out_area, &output_title(app, spinner_frame), title_style());
    let out_lines = ansi::parse(&app.output);
    draw_lines(buf, out_inner, &out_lines);
    if let (Some(err), Some(err_area)) = (&app.stderr, err_area) {
        let err_inner = draw_block(buf, err_area, " Stderr ", title_style());
        let err_lines = ansi::parse(err);
        draw_lines(buf, err_inner, &err_lines);
    }

    cursor
}
