    }));
}

fn run_tui(app: &mut App) -> Result<(), Error> {
    terminal::enable_raw_mode()?;
    {
        let mut stderr = io::stderr();
        execute!(stderr, EnterAlternateScreen)?;
    }
    install_panic_hook();

    let result = event_loop(app);

    let mut stderr = io::stderr();
    let _ = execute!(stderr, LeaveAlternateScreen);
    let _ = terminal::disable_raw_mode();
    result
}

fn event_loop(app: &mut App) -> Result<(), Error> {
    let mut term = tui::Terminal::new()?;
    let start = Instant::now();
    loop {
        let frame = ((start.elapsed().as_millis() / 100) % 6) as usize;
        term.draw(|buf| ui::draw(app, buf, frame))?;

        if event::poll(Duration::from_millis(100))? {
            match event::read()? {
                Event::Key(key) => {
                    if key.kind == KeyEventKind::Release {
                        continue;
                    }
                    match app.handle_key(key) {
                        Action::None => {}
                        Action::Exit => {
                            app.push_history();
                            return Ok(());
                        }
                        Action::RunHelpViewer(cmd) => {
                            run_viewer(&mut term, || {
                                Command::new("bash").arg("-c").arg(&cmd).status().map(|_| ())
                            });
                        }
                        Action::RunOutputViewer(cmd) => {
                            let output = app.output.clone();
                            run_viewer(&mut term, || {
                                let mut child = Command::new(&cmd).stdin(Stdio::piped()).spawn()?;
                                if let Some(mut stdin) = child.stdin.take() {
                                    let _ = stdin.write_all(output.as_bytes());
                                }
                                child.wait().map(|_| ())
                            });
                        }
                    }
                }
                _ => {}
            }
        }
        while let Ok(res) = app.executor.rx.try_recv() {
            app.handle_exec_result(res);
        }
        if app.should_exit {
            return Ok(());
        }
    }
}

/// Leaves the alternate screen, runs `f` and re-enters the alternate screen if
/// the viewer could be started.
fn run_viewer<F: FnOnce() -> io::Result<()>>(term: &mut tui::Terminal, f: F) {
    let mut stderr = io::stderr();
    let _ = execute!(stderr, LeaveAlternateScreen);
    let res = f();
    if res.is_ok() {
        let _ = queue!(stderr, EnterAlternateScreen);
        let _ = stderr.flush();
        term.invalidate();
    }
}
