new='''fn run_loop(req_rx: Receiver<ExecRequest>, res_tx: Sender<ExecResult>, eval_env: Vec<String>, isolation: bool, timeout: Duration) {
    let mut running: Option<Running> = None;
    loop {
        let req = if let Some(r) = &mut running {
            // give the running process a short time slice before looking for
            // new requests, so that quick commands can finish
            let slice_end = Instant::now() + Duration::from_millis(10);
            let mut finished: Option<std::io::Result<Option<std::process::ExitStatus>>> = None;
            loop {
                match r.child.try_wait() {
                    Ok(Some(status)) => {
                        finished = Some(Ok(Some(status)));
                        break;
                    }
                    Ok(None) => {}
                    Err(e) => {
                        finished = Some(Err(e));
                        break;
                    }
                }
                if Instant::now() >= slice_end {
                    break;
                }
                thread::sleep(Duration::from_millis(1));
            }
            match finished {
                Some(Ok(Some(status))) => {
                    // the pipes are only read once the process has finished
                    let stdout = read_all(r.child.stdout.take());
                    let stderr = read_all(r.child.stderr.take());
                    let _ = res_tx.send(ExecResult::Finished { success: status.success(), stdout, stderr });
                    running = None;
                }
                Some(Err(_)) => {
                    let _ = res_tx.send(ExecResult::Finished {
                        success: false,
                        stdout: String::new(),
                        stderr: String::new(),
                    });
                    running = None;
                }
                _ => {
                    if r.started.elapsed() >= timeout {
                        let _ = res_tx.send(ExecResult::TimedOut);
                        // the process itself is left alone
                        running = None;
                    }
                }
            }
            match req_rx.try_recv() {
                Ok(r) => Some(r),
                Err(std::sync::mpsc::TryRecvError::Empty) => None,
                Err(std::sync::mpsc::TryRecvError::Disconnected) => return,
            }
        } else {
            match req_rx.recv() {
                Ok(r) => Some(r),
                Err(_) => return,
            }
        };
        if let Some(mut req) = req {
            // only the most recent request matters
            while let Ok(newer) = req_rx.try_recv() {
                req = newer;
            }
            if let Some(mut r) = running.take() {
                let _ = r.child.kill();
                let _ = r.child.wait();
            }
            match spawn(&eval_env, isolation, &req) {
                Some(r) => running = Some(r),
                None => {
                    let _ = res_tx.send(ExecResult::Finished {
                        success: false,
                        stdout: String::new(),
                        stderr: String::new(),
                    });
                }
            }
        }
    }
}

