use crate::toml::Value;

/// Lenient conversion of a value into a boolean.
fn into_bool(v: &Value) -> Option<bool> {
    match v {
        Value::Boolean(b) => Some(*b),
        Value::Integer(i) => Some(*i != 0),
        Value::Float(f) => Some(*f != 0.0),
        Value::String(s) => match s.to_lowercase().as_str() {
            "1" | "true" | "on" | "yes" => Some(true),
            "0" | "false" | "off" | "no" => Some(false),
            _ => None,
        },
        _ => None,
    }
}

/// Lenient conversion of a value into an integer.
fn into_int(v: &Value) -> Option<i64> {
    match v {
        Value::Integer(i) => Some(*i),
        Value::Boolean(b) => Some(if *b { 1 } else { 0 }),
        Value::Float(f) => Some(f.round() as i64),
        Value::String(s) => s.parse::<i64>().ok(),
        _ => None,
    }
}

fn into_uint(v: &Value) -> Option<u64> {
    into_int(v).and_then(|i| if i < 0 { None } else { Some(i as u64) })
}

/// Lenient conversion of a value into a string.
fn into_string(v: &Value) -> Option<String> {
    match v {
        Value::String(s) => Some(s.clone()),
        Value::Boolean(b) => Some(b.to_string()),
        Value::Integer(i) => Some(i.to_string()),
        Value::Float(f) => Some(f.to_string()),
        _ => None,
    }
}

